/* 懒加载：用到哪张才解码哪张。
   开机全量 new Image() 会把 195 张一次性解码成 213 MB 位图，手机上直接被系统杀掉。
   缓存在 _cache 里，保证同一个键永远返回同一个对象（drawFish 有身份比较）；
   ART_SRC 里没有的键返回 undefined（fishFrames 靠假值 break，否则死循环）。 */
const ART_IMG = (function(){
  const cache = {};
  const make = k => {
    if(k in cache) return cache[k];
    const src = ART_SRC[k];
    if(!src) return undefined;
    if(typeof Image !== "function") return undefined;   // Node 测试环境没有 Image
    const im = new Image();
    im.decoding = "async";
    im.src = src;
    cache[k] = im;
    return im;
  };
  if(typeof Proxy !== "function"){                      // 兜底：不支持 Proxy 就退回原来的全量加载
    const all = {};
    if(typeof Image === "function") for(const k in ART_SRC){ const im = new Image(); im.src = ART_SRC[k]; all[k] = im; }
    return all;
  }
  return new Proxy(cache, {
    get: (t, k) => (typeof k === "string" ? make(k) : t[k]),
    has: (t, k) => typeof k === "string" && k in ART_SRC,
    ownKeys: () => Object.keys(ART_SRC),
    getOwnPropertyDescriptor: (t, k) => (k in ART_SRC)
      ? {configurable: true, enumerable: true, value: make(k)} : undefined
  });
})();
/* 当前海域的背景和牌子先预热一张，避免进场那一帧落回代码绘制的渐变。
   只热当前这一段，不是九段全热 —— 九段全热就退回原来的问题了。 */
function warmStage(){
  try{
    const s = curStage();
    void ART_IMG[s.key]; void ART_IMG[s.plaque];
  }catch(e){}
}
/* ══ 分段场景 ══
   按累计掌握词数推进，不做章节门禁（门禁会和记忆调度打架）。
   plaque 那一列是"这段背景该配哪套单词牌"：
   背景亮度从 19（深渊）跨到 190（浅海），差十倍，
   一套牌用到底必然有几段看不清 —— 亮背景配深色石板，暗背景配亮色贝壳。 */
const STAGES = [
  {at:0,    key:"bg_s1_shallow", name:"浅海沙地", plaque:"plaque_wood",  edge:"#C9A76B"},
  {at:100,  key:"bg_s2_reef",    name:"珊瑚礁",   plaque:"plaque_wood",  edge:"#E2603F"},
  {at:300,  key:"bg_s3_volt",    name:"电流海域", plaque:"plaque_stone", edge:"#2E7CA6"},
  {at:600,  key:"bg_s4_abyss",   name:"深渊",     plaque:"plaque_pearl", edge:"#1B4B66"},
  {at:1000, key:"bg_s5_jelly",   name:"水母群",   plaque:"plaque_pearl", edge:"#7B5EA8"},
  {at:1500, key:"bg_s6_whale",   name:"蓝鲸海域", plaque:"plaque_wood",  edge:"#2F6FA8"},
  {at:2000, key:"bg_s7_palace",  name:"龙宫",     plaque:"plaque_stone", edge:"#2FA97C"},
  {at:2500, key:"bg_s8_temple",  name:"神殿遗迹", plaque:"plaque_pearl", edge:"#6B7A72"}
];
/* 每帧有十几处要问"现在哪一段"（背景、单词牌、鱼群、每条鱼各一次），
   而 stageIdx 要把三千条学习进度全表扫一遍 —— 实测占了 75% 的 CPU。
   段位只随掌握词数变化，最快也是答对一个词才动一次，所以缓存住：
   答题结算、换牌组、读档时主动失效，另加 400ms 兜底防漏。 */
let _stgIdx = -1, _stgAt = -1e9;
function stageDirty(){ _stgIdx = -1; _stgAt = -1e9; }
function stageIdx(){
  const t = Date.now();
  // 兜底时间从 400ms 放到 2500ms：所有会改掌握词数的地方都已经主动 stageDirty()，
  // 兜底只是防我漏了某处。400ms 时它仍占 10% CPU（每 9 帧全表扫一次三千条），
  // 2500ms 后基本归零，代价是万一真漏了，换段最多晚 2.5 秒显示。
  if(_stgIdx >= 0 && t - _stgAt < 2500) return _stgIdx;
  const n = masteredCount(deckItems());
  let i = 0;
  for(let k = 0; k < STAGES.length; k++) if(n >= STAGES[k].at) i = k;
  _stgIdx = i; _stgAt = t;
  return i;
}
function curStage(){ return STAGES[stageIdx()]; }
/* 有图用图、没图回退：本段的图 → 老的 bg_scene → 代码画渐变 */
function stageBg(){
  const s = curStage();
  const a = ART_IMG[s.key];
  if(a && a.complete && a.naturalWidth) return a;
  const b = ART_IMG.bg_scene;
  return (b && b.complete && b.naturalWidth) ? b : null;
}
function stagePlaque(){
  const s = curStage();
  const a = ART_IMG[s.plaque];
  if(a && a.complete && a.naturalWidth) return a;
  const w = ART_IMG.plaque_wood;
  return (w && w.complete && w.naturalWidth) ? w : null;
}

const ART_NAME = ["jelly", "crab", "puffer", "eel", "octopus"];
// 有立绘就用立绘，没有就回退到代码绘制 —— 所以缺图不会开天窗
function artFor(lv, scared){
  const base = ART_NAME[lv];
  const want = ART_IMG[base + (scared ? "_1" : "_0")];
  if(want && want.complete && want.naturalWidth) return want;
  const fb = ART_IMG[base + "_0"];
  return (fb && fb.complete && fb.naturalWidth) ? fb : null;
}

/* ========== 海怪 ========== */
const SKIN = [
  {f:"#7FD8F0", s:"#1E5F7A"}, {f:"#FF8A5B", s:"#8A3A18"},
  {f:"#FFD166", s:"#8A6A0B"}, {f:"#B39DFF", s:"#4B3A8F"},
  {f:"#FF6B6B", s:"#8C2020"}
];
function drawCreature(e){
  const k = SKIN[e.lv], x = e.x, y = e.y;
  const sq = 1 + Math.sin(e.age * 6) * .03 + e.hitT * .28;
  ctx.save(); ctx.translate(x, y); ctx.scale(1 / sq, sq);
  ctx.lineWidth = 3; ctx.lineJoin = "round"; ctx.lineCap = "round";
  ctx.fillStyle = k.f; ctx.strokeStyle = k.s;
  const scared = e.y > seaY - 190;
  const sw = Math.sin(e.age * 2.2) * 4;
  const img = artFor(e.lv, scared);
  if(img){
    // 锚点让立绘底边落在 +42 附近，正好在牌子上沿，不压住触手
    const HH = 118, WW = HH * img.naturalWidth / img.naturalHeight;
    ctx.drawImage(img, -WW / 2, -HH * 0.645, WW, HH);
    ctx.restore();
    ropesAndPlate(e, x, y);
    return;
  }
  if(e.lv === 0){
    const T = [[[-20,0],[-26,20],[-20,38]], [[-7,2],[-3,24],[-8,42]],
               [[7,2],[3,24],[8,42]], [[20,0],[26,20],[20,38]]];
    ctx.strokeStyle = k.s; ctx.lineWidth = 8; tent.apply(null, T);
    ctx.strokeStyle = k.f; ctx.lineWidth = 4; tent.apply(null, T);
    ctx.fillStyle = k.f; ctx.strokeStyle = k.s; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(0, 0, 27, Math.PI, 0); ctx.closePath(); ctx.fill(); ctx.stroke();
    belly(0, -6, 19, 11, "#FFFFFF");
    ctx.fillStyle = "#FFFFFF"; ctx.globalAlpha = .45;
    circle(-11, -17, 3.4, false); circle(2, -21, 2.6, false); circle(12, -15, 2.2, false);
    ctx.globalAlpha = 1;
    eyes(0, -12, 10, scared ? 9 : 7, 0);
    blush(0, -4, 17, "#7FD8F0");
  }else if(e.lv === 1){
    ctx.lineWidth = 4; ctx.strokeStyle = k.s;
    for(const s of [-1, 1]) for(let i = 0; i < 2; i++){
      line(s * (16 + i * 12), 16, s * (26 + i * 12), 32);
    }
    ctx.lineWidth = 5;
    line(-26, -4, -36, -10); line(26, -4, 36, -10);
    ctx.fillStyle = k.f; ctx.lineWidth = 3;
    for(const s of [-1, 1]){ ell(s * 44, -16 + sw * .4, 11, 6, s * -.5); ell(s * 44, -5, 11, 6, s * .38); }
    ctx.lineWidth = 3; ctx.strokeStyle = k.s;
    line(-9, -20, -12, -34); line(9, -20, 12, -34);
    ctx.fillStyle = k.f; ell(0, 0, 31, 22, 0);
    belly(0, 6, 20, 10, "#FFD9C4");
    ctx.strokeStyle = k.s; ctx.lineWidth = 2; ctx.globalAlpha = .5;
    line(-16, -8, -8, -14); line(0, -11, 0, -17); line(16, -8, 8, -14);
    ctx.globalAlpha = 1;
    eyes(0, -38, 12, scared ? 9 : 7, 0);
    blush(0, 2, 21, "#FF6B6B");
  }else if(e.lv === 2){
    ctx.strokeStyle = k.s; ctx.lineWidth = 4;
    for(let i = 0; i < 10; i++){
      const a = i * Math.PI / 5;
      line(Math.cos(a) * 27, Math.sin(a) * 27, Math.cos(a) * 38, Math.sin(a) * 38);
    }
    ctx.fillStyle = k.f; ctx.lineWidth = 3;
    ell(-30, 4 + sw * .5, 9, 12, -.3); ell(30, 4 - sw * .5, 9, 12, .3);
    circle(0, 0, 27, true);
    belly(0, 9, 17, 11, "#FFF1C9");
    eyes(0, -7, 11, scared ? 10 : 8, 0);
    blush(0, 4, 18, "#FF8A5B");
    ctx.fillStyle = "#FF8A5B"; ctx.strokeStyle = k.s; ctx.lineWidth = 2;
    ell(0, 13, scared ? 6 : 5, scared ? 6 : 4, 0);
  }else if(e.lv === 3){
    ctx.save(); ctx.rotate(-.14 + sw * .008);
    ctx.fillStyle = k.f; ctx.strokeStyle = k.s; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-24, 0); ctx.lineTo(-48, -17); ctx.lineTo(-42, 0);
    ctx.lineTo(-48, 17); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-6, -15); ctx.lineTo(2, -30); ctx.lineTo(12, -14);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ell(0, 0, 34, 16, 0);
    belly(2, 6, 24, 7, "#EDE6FF");
    ctx.strokeStyle = k.s; ctx.lineWidth = 2.5; ctx.globalAlpha = .45;
    line(-14, -12, -18, 11); line(-2, -14, -6, 13); line(10, -13, 7, 12);
    ctx.globalAlpha = 1;
    ctx.restore();
    eyes(8, -6, 10, scared ? 9 : 7, 0);
    ctx.strokeStyle = "#FFD166"; ctx.fillStyle = "#FFD166"; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-30, -26); ctx.lineTo(-38, -10); ctx.lineTo(-31, -10);
    ctx.lineTo(-36, 4); ctx.lineTo(-22, -14); ctx.lineTo(-30, -14); ctx.closePath();
    ctx.fill(); ctx.stroke();
  }else{
    const T = [[[-20,14],[-32,30],[-26,46]], [[-10,20],[-18,38],[-24,48]], [[0,22],[0,40],[1,50]],
               [[10,20],[18,38],[24,48]], [[20,14],[32,30],[26,46]]];
    ctx.strokeStyle = k.s; ctx.lineWidth = 13; tent.apply(null, T);
    ctx.strokeStyle = k.f; ctx.lineWidth = 8; tent.apply(null, T);
    ctx.fillStyle = "#FFD9D9"; ctx.globalAlpha = .8;
    for(const [dx, dy] of [[-27,34],[-15,40],[0,42],[15,40],[27,34]]) circle(dx, dy, 2.6, false);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#FFD166"; ctx.strokeStyle = "#8A6A0B"; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(-18, -28); ctx.lineTo(-12, -40); ctx.lineTo(-6, -31);
    ctx.lineTo(0, -45); ctx.lineTo(6, -31); ctx.lineTo(12, -40); ctx.lineTo(18, -28);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.fillStyle = "#E24B4A"; circle(0, -37, 2.8, false); circle(-12, -33, 2.2, false);
    circle(12, -33, 2.2, false);
    ctx.fillStyle = k.f; ctx.strokeStyle = k.s; ctx.lineWidth = 3;
    circle(0, 0, 30, true);
    belly(0, 8, 20, 12, "#FFD9D9");
    eyes(0, -6, 11, scared ? 12 : 10, 0);
    blush(0, 8, 21, "#8C2020");
  }
  ctx.restore();
  ropesAndPlate(e, x, y);
}
function ropesAndPlate(e, x, y){
  const top = artFor(e.lv, false) ? 36 : 24;     // 用立绘时挂绳短一点
  ctx.strokeStyle = SKIN[e.lv].s; ctx.lineWidth = 2.5; ctx.globalAlpha = .8;
  line(x - 13, y + top, x - 9, y + 46); line(x + 13, y + top, x + 9, y + 46);
  ctx.globalAlpha = 1;
  plate(e);
}
function line(a, b, c, d){ ctx.beginPath(); ctx.moveTo(a, b); ctx.lineTo(c, d); ctx.stroke(); }
function ell(x, y, rx, ry, rot){
  ctx.beginPath(); ctx.ellipse(x, y, rx, ry, rot, 0, 6.2832); ctx.fill(); ctx.stroke();
}
function tent(){
  for(const p of arguments){
    ctx.beginPath(); ctx.moveTo(p[0][0], p[0][1]);
    ctx.quadraticCurveTo(p[1][0], p[1][1], p[2][0], p[2][1]); ctx.stroke();
  }
}
/* ══ 九宫格拉伸 ══
   四角保持原样不变形，上下边横向拉、左右边纵向拉、中间双向拉。
   边框比例按图宽的 12% 取 —— 这就是出图时要求"四边边框宽度均匀"的原因，
   边框不匀的话切出来的九块会错位。 */
function nineSlice(img, x, y, w, h){
  const iw = img.naturalWidth, ih = img.naturalHeight;
  if(!iw || !ih) return;
  let b = Math.round(Math.min(iw, ih) * 0.30);       // 源图上的边框宽度
  b = Math.max(4, Math.min(b, Math.floor(Math.min(iw, ih) / 2) - 1));
  // 目标边框：不能超过目标尺寸的一半，否则九块会互相叠
  const bw = Math.max(2, Math.min(b, Math.floor(w / 2) - 1));
  const bh = Math.max(2, Math.min(b, Math.floor(h / 2) - 1));
  const sMidW = iw - b * 2, sMidH = ih - b * 2;
  const dMidW = w - bw * 2, dMidH = h - bh * 2;
  const D = (sx, sy, sw, sh, dx, dy, dw, dh) => {
    if(sw <= 0 || sh <= 0 || dw <= 0 || dh <= 0) return;
    ctx.drawImage(img, sx, sy, sw, sh, dx, dy, dw, dh);
  };
  // 四角
  D(0, 0, b, b, x, y, bw, bh);
  D(iw - b, 0, b, b, x + w - bw, y, bw, bh);
  D(0, ih - b, b, b, x, y + h - bh, bw, bh);
  D(iw - b, ih - b, b, b, x + w - bw, y + h - bh, bw, bh);
  // 四边
  D(b, 0, sMidW, b, x + bw, y, dMidW, bh);
  D(b, ih - b, sMidW, b, x + bw, y + h - bh, dMidW, bh);
  D(0, b, b, sMidH, x, y + bh, bw, dMidH);
  D(iw - b, b, b, sMidH, x + w - bw, y + bh, bw, dMidH);
  // 中心
  D(b, b, sMidW, sMidH, x + bw, y + bh, dMidW, dMidH);
}
/* 石板和贝壳的牌面明暗差很大，文字颜色要跟着换 */
function plaqueIsDark(){
  const p = curStage().plaque;
  return p === "plaque_stone" || p === "input_stone";
}
function plate(e){
  const pad = 13, lines = e.disp, maxW = Math.max(120, W - 24);
  let fs = 15, raw = 0;
  for(let guard = 0; guard < 8; guard++){
    raw = 0;
    for(const l of lines){
      ctx.font = fontOf(l, fs);
      raw = Math.max(raw, ctx.measureText(l.t).width);
    }
    if(raw + pad * 2 <= maxW || fs <= 9) break;
    fs -= 1;
  }
  const photoOn = !!(e.photo && e.photo.complete && e.photo.naturalWidth);
  const photoH = photoOn ? 68 : 0;
  const w = Math.min(Math.max(raw + pad * 2, photoOn ? 108 : 92), maxW);
  const lh = fs + 5, h = lines.length * lh + 14 + photoH;
  const px = Math.max(8, Math.min(W - w - 8, e.x - w / 2));
  const cx = px + w / 2, py = e.y + 46;
  /* 这里坚持代码绘制，不用立绘。
     那三套牌子是给 2000px 宽的大面板画的，边框上有藤壶、海草这类密集细节；
     游戏里的牌子只有 50 来像素高，那些细节必然糊成一团，字还压不清。
     立绘挪到句子模式去用（那里一屏一个，能做到 700×160）。
     阶段感靠描边配色体现 —— 清晰度优先。 */
  ctx.fillStyle = "#FFF6E5";
  ctx.strokeStyle = curStage().edge || SKIN[e.lv].s;
  ctx.lineWidth = 2.5;
  roundRect(px, py, w, h, 9); ctx.fill(); ctx.stroke();
  if(photoOn){
    const side = 60, ix = cx - side / 2, iy = py + 6;
    ctx.save();roundRect(ix, iy, side, side, 8);ctx.clip();ctx.drawImage(e.photo, ix, iy, side, side);ctx.restore();
  }
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  lines.forEach((l, i) => {
    ctx.fillStyle = l.c || "#3A2E14";
    ctx.font = fontOf(l, fs);
    ctx.fillText(l.t, cx, py + 9 + photoH + lh / 2 + i * lh);
  });
  ctx.textAlign = "start"; ctx.textBaseline = "alphabetic";
}
function fontOf(l, fs){
  return l.m ? "600 " + fs + "px ui-monospace,Menlo,monospace"
             : "600 " + (fs - 2) + "px -apple-system,PingFang SC,sans-serif";
}

/* ========== 粒子 ========== */
let bits = [];
function burst(x, y, c){
  if(bits.length > CAP_BITS) bits.splice(0, bits.length - CAP_BITS);
  for(let i = 0; i < 16; i++){
    const a = Math.random() * 6.2832, v = 60 + Math.random() * 160;
    bits.push({x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 40, r: 3 + Math.random() * 5, life: .7, c});
  }
}
function drawBits(dt){
  for(const b of bits){
    b.life -= dt; b.x += b.vx * dt; b.y += b.vy * dt; b.vy += 420 * dt;
  }
  bits = bits.filter(b => b.life > 0);
  for(const b of bits){
    ctx.globalAlpha = Math.max(0, b.life / .7);
    ctx.fillStyle = b.c; circle(b.x, b.y, b.r, false);
  }
  ctx.globalAlpha = 1;
}
const CAP_BITS = 420, CAP_RINGS = 40, CAP_FLOATS = 30;
function sparkle(x, y, c, n){
  if(bits.length > CAP_BITS) return;
  for(let i = 0; i < (n || 5); i++){
    const a = Math.random() * 6.2832, v = 30 + Math.random() * 80;
    bits.push({x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 30, r: 1.5 + Math.random() * 2.5, life: .38, c});
  }
}
let rings = [];
function ring(x, y, c, w, sp){
  if(rings.length > CAP_RINGS) rings.shift();
  rings.push({x, y, r: 8, life: .55, c, w: w || 4, sp: sp || 1});
}
function drawRings(dt){
  for(const r of rings){ r.life -= dt; r.r += 300 * r.sp * dt; }
  rings = rings.filter(r => r.life > 0);
  for(const r of rings){
    ctx.globalAlpha = Math.max(0, r.life / .55);
    ctx.strokeStyle = r.c; ctx.lineWidth = r.w;
    ctx.beginPath(); ctx.arc(r.x, r.y, r.r, 0, 6.2832); ctx.stroke();
  }
  ctx.globalAlpha = 1;
}
let floats = [];
function popText(x, y, t, c, size){
  if(floats.length > CAP_FLOATS) floats.shift();
  floats.push({x, y, t, c, life: 1, s: size || 20});
}
function drawFloats(dt){
  for(const f of floats){ f.life -= dt; f.y -= 46 * dt; }
  floats = floats.filter(f => f.life > 0);
  ctx.textAlign = "center";
  for(const f of floats){
    ctx.globalAlpha = Math.min(1, f.life);
    ctx.font = "700 " + f.s + "px -apple-system,PingFang SC,sans-serif";
    ctx.fillStyle = f.c; ctx.fillText(f.t, f.x, f.y);
  }
  ctx.globalAlpha = 1; ctx.textAlign = "start";
}

/* ========== 音频 ========== */
let AC = null, MASTER = null;
function actx(){ if(!AC) AC = new (window.AudioContext || window.webkitAudioContext)(); return AC; }
function master(){
  if(!MASTER){ MASTER = actx().createGain(); MASTER.gain.value = 1; MASTER.connect(actx().destination); }
  return MASTER;
}
function sfxVol(){
  const v=Number(S.sfx);
  return Number.isFinite(v)?Math.max(0,Math.min(1,v)):0.65;
}
function resumeAudio(){
  try{ if(AC && AC.state === "suspended") AC.resume(); }catch(e){}
}
function midi(n){ return 440 * Math.pow(2, (n - 69) / 12); }
function tone(freq, at, dur, type, vol){
  if(vol <= 0) return;
  try{
    const a = actx(), o = a.createOscillator(), g = a.createGain();
    o.type = type || "sine"; o.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, at);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), at + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    o.connect(g); g.connect(master());
    o.start(at); o.stop(at + dur + 0.03);
  }catch(e){}
}
function beep(freq, dur, type, vol){
  try{ tone(freq, actx().currentTime, dur || .12, type, (vol || .12) * sfxVol()); }catch(e){}
}
// 敲对一个字母：音高随连续正确数往上爬，另叠一层短促咔哒增加敲击感
function keyTone(){
  try{
    const n = Math.min(keyStreak, 15), t = actx().currentTime;
    const f = midi(67 + [0,2,4,5,7,9,11,12][n % 8] + Math.floor(n / 8) * 12);
    tone(f, t, .09, "triangle", .085 * sfxVol());
    tone(f * 1.5, t, .04, "sine", .018 * sfxVol());
  }catch(e){}
}
// 锁定一个新目标：一声轻微的低音，提示「开始打这只了」
function lockTone(){
  try{ tone(midi(52), actx().currentTime, .07, "sine", .05 * sfxVol()); }catch(e){}
}
// 打完一整个词：两音上行，和单字母的短音明显区分开
function wordTone(n){
  try{
    const t = actx().currentTime, base = 74 + Math.min(n, 10);
    tone(midi(base), t, .17, "triangle", .12 * sfxVol());
    tone(midi(base + 7), t + .055, .22, "triangle", .1 * sfxVol());
    tone(midi(base + 12), t + .1, .26, "sine", .06 * sfxVol());
  }catch(e){}
}
// 连击里程碑：一串上行琶音
function flourish(level){
  try{
    const t = actx().currentTime, base = 72 + Math.min(level, 3) * 2;
    [0, 4, 7, 12].forEach((s, i) => tone(midi(base + s), t + i * .055, .3, "triangle", .075 * sfxVol()));
  }catch(e){}
}

/* ---- 背景音乐：五声音阶循环，全程合成，无音频文件 ---- */
const BPM = 104, SCALE = [0, 2, 4, 7, 9, 12, 14, 16];
const CHORDS = [0, -3, 5, 7];                 // C - Am - F - G
const PAT = [0, 2, 4, 2, 5, 4, 2, 0];         // 旋律骨架（SCALE 下标）
const REST = [0, 1, 0, 0, 1, 0, 0, 1];        // 1 = 该拍留白
let bgmTimer = null, bgmStep = 0, bgmNext = 0;
function bgmVol(){ return S.bgm || 0; }
function bgmSchedule(){
  try{
    const a = actx(), spb = 60 / BPM / 2, look = .3, v = bgmVol();
    if(bgmNext < a.currentTime) bgmNext = a.currentTime + .05;
    while(bgmNext < a.currentTime + look){
      const st = bgmStep, at = bgmNext, bar = Math.floor(st / 8) % 4, pos = st % 8;
      const root = CHORDS[bar];
      // 低音
      if(pos === 0) tone(midi(45 + root), at, .55, "sine", .085 * v);
      if(pos === 4) tone(midi(45 + root + 7), at, .4, "sine", .06 * v);
      // 铺底和弦：整小节铺一层，把空隙填满
      if(pos === 0){
        tone(midi(57 + root), at, spb * 7.2, "sine", .028 * v);
        tone(midi(64 + root), at, spb * 7.2, "sine", .022 * v);
      }
      // 旋律 + 一层回声，做出空间感
      if(!REST[pos]){
        const n = midi(72 + root + SCALE[PAT[(pos + bar) % 8]]);
        tone(n, at, .3, "triangle", .052 * v);
        tone(n, at + .21, .26, "sine", .018 * v);
      }
      // 轻打点，第 4 拍稍重
      if(pos % 2 === 1) tone(midi(96), at, .035, "square", (pos === 3 ? .02 : .012) * v);
      bgmNext += spb; bgmStep++;
    }
  }catch(e){}
}
function startBgm(){
  stopBgm();                       // 幂等：重复调用不会叠加定时器
  if(!bgmVol()) return;
  try{ actx().resume(); }catch(e){}
  bgmStep = 0; bgmNext = 0;
  bgmSchedule();
  bgmTimer = setInterval(bgmSchedule, 120);
}
function stopBgm(){
  if(bgmTimer){ clearInterval(bgmTimer); bgmTimer = null; }
}
function pickVoice(lang){
  try{
    const vs = speechSynthesis.getVoices() || [];
    const pre = lang.slice(0, 2).toLowerCase();
    return vs.find(v => v.lang && v.lang.toLowerCase().slice(0, 2) === pre) || null;
  }catch(e){ return null; }
}
function speak(text, lang, chain){
  try{
    if(!window.speechSynthesis || !text) return;
    const L = lang || "en-US";
    const v = pickVoice(L);
    // 系统里没装对应语音时直接跳过 —— 硬念会把队列卡死，之后所有朗读都不出声
    if(!v && L !== "en-US") return;
    if(!chain){ try{ speechSynthesis.cancel(); }catch(e){} }
    const u = new SpeechSynthesisUtterance(text);
    u.lang = L; if(v) u.voice = v;
    u.rate = L === "zh-CN" ? Math.min(1, (S.rate || .85) + .1) : (S.rate || .85);
    speechSynthesis.speak(u);
    // Chrome 偶发把朗读卡在暂停态，主动踢一下
    setTimeout(() => { try{ if(speechSynthesis.paused) speechSynthesis.resume(); }catch(e){} }, 80);
  }catch(e){}
}
// 取第一个义项就好，整串念出来太长
function firstSense(zh){
  return String(zh || "").split(/[；;，,、]/)[0].replace(/[（(][^)）]*[)）]/g, "").trim();
}
// 答对之后才念：先英文，再中文
function speakWord(item){
  speak(item.w, "en-US");
  if(S.zhVoice && item.zh) speak(firstSense(item.zh), "zh-CN", true);
}
let toastT = null;
function toast(msg){
  const el = document.getElementById("toast");
  el.textContent = msg; el.classList.add("on");
  clearTimeout(toastT);
  toastT = setTimeout(() => el.classList.remove("on"), 1300);
}
function setSpeed(mul, announce){
  const old = S.speed || 1.4;
  if(mul === old) return;
  for(const e of enemies) if(!e.dead) e.vy = e.vy * old / mul;
  S.speed = mul; save();
  if(announce){
    const name = (SPEEDS.find(s => s[1] === mul) || ["自定义"])[0];
    toast("下落速度：" + name);
  }
}
function bumpSpeed(dir){
  let i = SPEEDS.findIndex(s => s[1] === S.speed);
  if(i < 0) i = 2;
  i = Math.max(0, Math.min(SPEEDS.length - 1, i + dir));
  setSpeed(SPEEDS[i][1], true);
}

/* ========== 游戏 ========== */
let mode = "home";
let enemies = [], eid = 0, queue = [], planned = 0;
let lives = 5, combo = 0, bestCombo = 0, kills = 0, misses = 0, keyOk = 0, keyBad = 0;
let keyStreak = 0, bestStreak = 0, milestone = 0;
let activeBoost = null, boostSpeed = 1, killsByTier = {}, relearned = new Set();
/* 本局养分的加权份数。每击碎一个词记一份，栽过的词记得多一点 ——
   见 destroy()。不加权的话，滚瓜烂熟的词和刚救回来的硬骨头一样值钱。
   allKillsShown / clearBonusShown 是给结算面板显示用的：它们在
   settleFarm 里算出来，面板在另一个函数里，得存下来。 */
let nutUnits = 0, allKillsShown = 0, clearBonusShown = 1;
let startedWithDue = false;
function hasDueWork(){
  const t=Date.now();
  return Object.values(S.prog||{}).some(p=>p&&(p.lv>0||p.ok>0||p.bad>0)&&Number(p.due)<=t)
    ||Object.values(S.wordState||{}).some(p=>p&&p.status!=='new'&&Number(p.dueAt)<=t);
}
function rewardDay(){const d=new Date();return [d.getFullYear(),d.getMonth()+1,d.getDate()].join('-')}
// 本局喂过农场的词（用于收获溯源）：击碎时记一条，含当时的累计失败次数
let sessFed = [];
let coinBreak = {kill:0, combo:0, learn:0, master:0, perfect:0}, nutGain = [];
let ups = 0, newLearned = 0, newMastered = 0, changed = [];
let spawnCd = 0, damageFlash = 0, last = 0;
let buf = "", target = null;

function maskOf(ans, n){
  let out = "";
  for(let i = 0; i < ans.length; i++){
    const ch = ans[i];
    out += (i < n) ? ch : (ch === " " ? " " : "_");
  }
  return out;
}
function refreshDisp(e){
  const lv = e.lv, a = e.answer, n = e.typed.length;
  const L = [];
  if(lv === 0){ L.push({t: e.item.zh, c: "#96805A"}); L.push({t: a, m: 1, c: "#3A2E14"}); }
  else if(lv === 1){ L.push({t: e.item.zh, c: "#5C4A22"});
    L.push({t: maskOf(a, Math.max(1, n)), m: 1, c: "#8A6A0B"}); }
  else if(lv === 2){ L.push({t: e.item.zh, c: "#5C4A22"}); L.push({t: maskOf(a, n), m: 1, c: "#8A6A0B"}); }
  else { L.push({t: lv >= 4 ? "听音拼写 · 精通关" : "听音拼写（Tab 重听）", c: "#5C4A22"});
    L.push({t: maskOf(a, n), m: 1, c: "#8A6A0B"}); }
  // 浮标：Lv2 及以上补一个首字母，代价是这个词本局不计升级
  if(e.hinted && n === 0) L[1] = {t: maskOf(a, 1), m: 1, c: "#B5734F"};
  e.disp = L;
}
function spawn(item){
  const p = progOf(item), lv = item && item._battleLv != null ? Math.max(1,Math.min(4,item._battleLv|0)) : p.lv;
  const answer = norm(item.w);
  const chars = answer.length;
  const dur = ((1.5 + chars / Math.max(1.2, S.cps)) * LV_MULT[lv] * TIER_MULT[item.t]
            + (item.kind === "s" ? 1.4 : 0)) * (S.speed || 1.4) * boostSpeed;
  const e = {
    id: ++eid, item, lv, answer, typed: "", x: 0, y: -70,
    vy: (seaY - 30 + 70) / dur, age: 0, hitT: 0, dead: false, disp: []
  };
  if(item && item.img){ e.photo = new Image(); e.photo.decoding = "async"; e.photo.src = item.img; }
  const margin = Math.min(110, W * .25);
  e.x = margin + Math.random() * Math.max(1, W - margin * 2);
  const near = enemies.filter(o => !o.dead && Math.abs(o.x - e.x) < 150 && o.y < 120);
  if(near.length) e.x = e.x + (Math.random() < .5 ? -170 : 170);
  e.x = Math.max(margin, Math.min(W - margin, e.x));
  e.hinted = (activeBoost === "buoy" && lv >= 2);
  refreshDisp(e);
  enemies.push(e);
  // Lv3/Lv4 是听音关，必须朗读；其余等级只有开了「出现时朗读」才念，否则等于直接报答案
  if(lv >= 3 || S.voice === "spawn") speak(item.w);
}
function startGame(){
  const s = buildSession();
  if(!s.queue.length){
    alert("今天没有到期的词，也没有新词了。明天再来，或者换个词库。");
    return;
  }
  queue = s.queue.slice(); planned = queue.length;
  enemies = []; bits = []; floats = []; rings = [];
  lives = 5; combo = 0; bestCombo = 0; kills = 0; misses = 0;
  keyStreak = 0; bestStreak = 0; milestone = 0;
  keyOk = 0; keyBad = 0; ups = 0; newLearned = 0; newMastered = 0; changed = [];
  buf = ""; target = null; spawnCd = .5; damageFlash = 0;
  // 装备的增益在开局消耗，用掉才扣
  activeBoost = null; boostSpeed = 1;
  killsByTier = {}; nutGain = []; relearned = new Set();
  nutUnits = 0;
  startedWithDue=hasDueWork();
  sessFed = [];
  coinBreak = {kill:0, combo:0, learn:0, master:0, perfect:0};
  const eq = S.farm.equipped;
  if(eq && S.farm.boosts[eq] > 0){
    activeBoost = eq;
    S.farm.boosts[eq]--;
    if(S.farm.boosts[eq] <= 0) S.farm.equipped = null;
    if(eq === "slow") boostSpeed = 1.3;
    if(eq === "deep") boostSpeed = 0.7;
    if(eq === "reef") lives = 7;
    save();
  }
  mode = "play";
  startBgm();
  document.getElementById("hud").classList.add("on");
  showScreen(null);
  updateHud();
  focusMobKey();          // 手机上把系统键盘叫出来，否则一个字都打不了
  last = performance.now();
}
/* 连续记录：词潮和句潮共用 S.lastPlay，格式必须只有一种。
   （踩过的坑：词潮存日期字符串、句子模块存天数数字，同一天玩两种模式
     会互相判成"不是今天"，连续记录被反复重置成 1。） */
function markPlayDay(){
  const today = new Date().toDateString();
  if(S.lastPlay === today) return;
  const y = new Date(Date.now() - DAY).toDateString();
  S.streak = (S.lastPlay === y) ? (S.streak || 0) + 1 : 1;
  S.lastPlay = today;
}
function endGame(){
  mode = "result";
  stopBgm();
  blurMobKey();           // 收起手机键盘，不然结算页被压掉半屏
  document.getElementById("hud").classList.remove("on");
  markPlayDay();
  if(bestCombo > (S.best || 0)) S.best = bestCombo;
  settleFarm();
  save();
  const total = keyOk + keyBad;
  document.getElementById("rAcc").textContent = total ? Math.round(keyOk / total * 100) + "%" : "—";
  document.getElementById("rKill").textContent = kills;
  document.getElementById("rMiss").textContent = misses;
  document.getElementById("rCombo").textContent = bestCombo;
  document.getElementById("rStreak").textContent = bestStreak;
  document.getElementById("rUp").textContent = ups;
  document.getElementById("rNew").textContent = newLearned;
  document.getElementById("rMas").textContent = newMastered;
  document.getElementById("rTitle").textContent = lives > 0 ? "本局结束" : "防线被冲垮了";
  document.getElementById("rNote").textContent = lives > 0
    ? "漏掉的词已经降级并重新排队，明天还会再来找你。"
    : "防线归零不扣任何进度，答过的词照常结算。";
  renderHarvestPanel();
  const box = document.getElementById("rList");
  box.innerHTML = changed.length ? "" : '<div class="muted" style="padding:12px">本局没有等级变化。</div>';
  for(const c of changed.slice(0, 60)){
    const d = document.createElement("div");
    const up = c.after > c.before;
    d.innerHTML = '<em class="' + (up ? "ok" : "warn") + '">' + (up ? "升 Lv" + c.after : "降 Lv" + c.after) +
      '</em><b style="flex:none;width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' +
      esc(c.w) + '</b><span style="color:#96805A;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(c.zh) + '</span>';
    box.appendChild(d);
  }
  showScreen("scResult");
}
function esc(s){ return String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }

/* ========== 农场结算 ========== */
function accuracy(){ const t = keyOk + keyBad; return t ? keyOk / t : 0; }
function settleFarm(){
  if(misses === 0 && keyBad === 0 && kills > 0) coinBreak.perfect = 10;
  const total = Math.round(coinBreak.kill + coinBreak.combo + coinBreak.learn
                         + coinBreak.master + coinBreak.perfect);
  S.farm.coin += total;
  // 养分：本档六成保底 + 四成看匹配；清空到期词 ×1.15；深潮增益 ×2
  /* 原来这里是「正确率 ≥90% → ×1.2」。删了 —— 它和整个系统的方向是反的：
     间隔重复最有效的复习点是"差点想不起来"，最优成功率约在 85–90%，
     高于这个说明练的东西太简单。奖励高正确率等于在说"别碰难的"，
     而系统本身又在推你练难词。两套信号打架，玩家会跟着钱走。 */
  /* dueCount() 定义在记忆模块里，这个作用域够不着 —— 第一版写成
     typeof dueCount === "function" 就永远是假，那条加成是死代码。
     S 是全局的，直接照它的口径数一遍。 */
  let clearBonus = 1;
  if(startedWithDue&&!hasDueWork()&&S.farm.dueBonusDay!==rewardDay()){
    clearBonus=1.15;
    if(kills>0&&S.farm.plots.some(p=>p&&CROPS[p.crop]&&p.nut<CROPS[p.crop].need))S.farm.dueBonusDay=rewardDay();
  }
  clearBonusShown = clearBonus;
  const deepBonus = activeBoost === "deep" ? 2 : 1;
  let allKills = 0;
  for(const k in killsByTier) allKills += killsByTier[k];
  allKillsShown = allKills;
  nutGain = [];
  const wx = curWeather();
  /* 养分是**一个池子**，按各地块的吸收力分配 —— 不是每块地都独立拿满。
     原来是独立拿满，于是"多开地 + 种最便宜最快熟的"能把产出乘上地块数：
     模拟里 12 块海草 60 局收了 232 次，币是其他策略的四倍，
     在币/珍珠/地块/增益四个维度上全面支配。那作物差异化就白做了。

     池子按 1/√n 缩放：多一块地仍然增加总产出（12 块地是 1 块的 3.5 倍），
     但不再是线性的 12 倍。扩地依然值得，只是不再是唯一的答案。 */
  const planted = S.farm.plots.filter(p => p && CROPS[p.crop]).length;
  const spread = planted ? 1 / Math.sqrt(planted) : 1;
  S.farm.plots.forEach((p, i) => {
    if(!p || !CROPS[p.crop]) return;
    const c = CROPS[p.crop];
    const matched = killsByTier[c.tier] || 0;
    const nb = growBonus(i);
    /* 原来是 matched + 0.3×others：同档词喂满，别档只给三成。
       听着合理，实测是死局 —— 前期只会出 T1/T2 词，T5 的深海珍珠贝
       每局只能拿到三成的三成，模拟里 60 局一次都没熟，珍珠经济压根没启动。
       改成"六成保底 + 四成看匹配"：档位仍然重要（匹配满档快 67%），
       但不会让高阶作物完全饿死。选新词的配比还是走 plantMix，不受影响。 */
    const share = allKills ? matched / allKills : 0;
    /* allKills 只是"打了几个"，nutUnits 是"救回来多少" —— 用后者。
       没有加权数据时（老存档、异常路径）退回 allKills，不至于给 0。 */
    const units = nutUnits > 0 ? nutUnits : allKills;
    const gain = units * (0.6 + 0.4 * share)
               * clearBonus * deepBonus * wx.nut * nb * spread;
    const before = p.nut;
    p.nut = Math.min(c.need, Math.round((p.nut + gain) * 10) / 10);
    // 溯源：这株是多少词喂出来的、哪个词栽得最多。
    // 收获时说得出"这株荧光水母花是 47 个词喂出来的，其中 abandon 让你栽了 3 次"，
    // 农场才像学习史的纪念品，而不是一个独立的挂机小游戏。
    if(gain > 0){
      p.fed = (p.fed | 0) + sessFed.length;
      p.dry = 0;
      const w = worstWord();
      if(w && (!p.worst || w.bad > p.worst.bad)) p.worst = {w: w.w, bad: w.bad};
    }else{
      p.dry = (p.dry | 0) + 1;      // 连续几局没喂到 → 界面上显示"饿了"
    }
    nutGain.push({i, crop: p.crop, before, after: p.nut, need: c.need,
                  gain: Math.round(gain * 10) / 10, nb: nb});
  });
  return total;
}
/* 收获的 0.8 秒：植物缩小飞散 → 闪光 → 币和珍珠飞向右上角的钱包。
   卡片布局下没有可飞的目标，所以只在地图模式下播；
   不管播不播，done() 一定会被调用，收获逻辑不依赖动画。 */
function reapFx(i, pay, pearl, done){
  let el = null;
  try{
    const box = document.getElementById("farmMap");
    if(mapMode() && box) el = box.querySelector('.fplot[data-plot="' + i + '"]');
  }catch(e){}
  if(!el){ done(); return; }
  el.classList.add("reap");
  const pop = el.parentNode.querySelector(".fpop");
  if(pop) pop.remove();
  const P = PLOTS[i] || {x:50, y:80};
  const add = (cls, html, dx, dy, delay) => {
    const s = document.createElement("span");
    s.className = cls;
    s.innerHTML = html;
    s.style.left = (P.x + dx) + "%";
    s.style.top = (P.y + dy) + "%";
    if(delay) s.style.animationDelay = delay + "s";
    el.parentNode.appendChild(s);
    setTimeout(() => s.remove(), 1400);
  };
  add("spark", "", 0, -4, 0);
  add("spark", "", 3, -8, .12);
  add("coinfly", "+" + pay, 0, -6, .05);
  if(pearl) add("coinfly", "+" + pearl + "◍", 4, -10, .18);
  setTimeout(done, 820);
}
/* 收获。产出分三部分：币（受天气影响）、珍珠、以及作物各自的 gift。
   gift 的意义是让六种作物没法排成一条"越贵越好"的线，见 CROPS 上面那段。 */
function harvest(i, pay){
  const f = S.farm, p = f.plots[i];
  if(!p || !CROPS[p.crop]) return;
  const c = CROPS[p.crop];
  const lines = [];
  f.coin += pay; lines.push(pay + " 币");
  // 水母花给相邻地块 +1 珍珠；更难获得的月潮莲给 +2。
  let lit = 0;
  for(const j of neighborsOf(i)){
    const q = f.plots[j];
    if(q && q.crop === "jelly") lit++;
    if(q && q.crop === "lotus") lit += 2;
  }
  const pearl = c.pearl + lit;
  if(pearl){ f.pearl += pearl; lines.push(pearl + " 颗珍珠"); }
  if(c.gift === "seed"){
    // 保底：海草和钢铁藤收获必给种子，所以永远不会因为没币没种子而卡死。
    // 海草给的是**六档里随机一颗**，不是必然还给海草 ——
    // 必然还给海草的话海草的边际成本就是零，模拟里它会把其他作物全比死。
    const normal=CROP_KEYS.filter(x=>!CROPS[x].rare);
    const k = p.crop === "vine" ? "vine"
            : normal[(Math.random() * normal.length) | 0];
    f.seeds[k] = (f.seeds[k] | 0) + 1;
    lines.push(CROPS[k].n + "种子 ×1");
  }else if(c.gift === "boost" || c.gift === "boost2" || c.gift === "boost3"){
    const times = c.gift === "boost3" ? 3 : (c.gift === "boost2" ? 2 : 1);
    for(let t = 0; t < times; t++){
      const k = BOOST_KEYS[(Math.random() * BOOST_KEYS.length) | 0];
      f.boosts[k] = (f.boosts[k] | 0) + 1;
      lines.push("增益「" + BOOSTS[k].n + "」×1");
    }
  }else if(c.gift === "nut"){
    // 收获时把养分分给邻居 —— 和珊瑚的"在地里时加成"是两条不同的路径：
    // 珊瑚要一直占着地，星光藻是收的那一刻给一次。摆法因此不一样。
    let fed = 0;
    for(const j of neighborsOf(i)){
      const q = f.plots[j];
      if(!q || !CROPS[q.crop]) continue;
      q.nut = Math.min(CROPS[q.crop].need, q.nut + 6);
      fed++;
    }
    if(fed) lines.push("给旁边 " + fed + " 块地各补 6 养分");
  }else if(c.gift === "rareseed"){
    // 传说作物只回赠稀有种子，不产凭空养分，也不触碰复习排程。
    const pool=RARE_CROPS.filter(k=>rareProgress(k).ok);
    const k=pool.length?pool[(Math.random()*pool.length)|0]:"lotus";
    f.seeds[k]=(f.seeds[k]|0)+1;
    lines.push(CROPS[k].n+"种子 ×1");
  }
  f.harvested++;
  const fed = p.fed | 0, worst = p.worst;
  f.plots[i] = null;
  save();
  // 先播 0.8 秒的收获动画，播完再重画地图 —— 直接重画的话植物会当场消失，
  // 那一下最该有的爽感就没了
  reapFx(i, pay, pearl, () => { refreshFarm(); });
  flourish(2);
  toast("收获 " + lines.join(" + "));
  // 这一条是整个农场改造里我最看重的：让收获指回学习本身
  if(fed > 0){
    const tail = worst ? ("，其中你在 " + worst.w + " 上栽过 " + worst.bad + " 次") : "";
    setTimeout(() => toast("这株" + c.n + "是 " + fed + " 个词喂出来的" + tail), 1500);
  }
}
/* 本局栽得最狠的那个词。bad 是累计失败次数，取本局出现过的词里最大的。 */
function worstWord(){
  let best = null;
  for(const r of sessFed) if(r.bad > 0 && (!best || r.bad > best.bad)) best = r;
  return best;
}
function coinTotal(){
  return Math.round(coinBreak.kill + coinBreak.combo + coinBreak.learn
                  + coinBreak.master + coinBreak.perfect);
}
function renderHarvestPanel(){
  const total = coinTotal();
  document.getElementById("rCoin").textContent = "+" + total;
  const rows = [
    ["击碎 " + kills + " 词", coinBreak.kill],
    ["连击里程碑 ×" + milestone, coinBreak.combo],
    ["新记住 " + newLearned + " 词", coinBreak.learn],
    ["新精通 " + newMastered + " 词", coinBreak.master],
    ["零失误奖励", coinBreak.perfect]
  ];
  const box = document.getElementById("rCoinBreak"); box.innerHTML = "";
  for(const [label, v] of rows){
    if(!v) continue;
    const d = document.createElement("div");
    d.innerHTML = '<em class="ok">' + esc(label) + '</em><span style="flex:1"></span><b>+' +
      Math.round(v) + "</b>";
    box.appendChild(d);
  }
  if(activeBoost){
    const d = document.createElement("div");
    d.innerHTML = '<em class="fixd">本局增益</em><span style="flex:1">' +
      esc(BOOSTS[activeBoost].n) + "</span>";
    box.appendChild(d);
  }
  const nb = document.getElementById("rNut"); nb.innerHTML = "";
  if(!nutGain.length){
    nb.innerHTML = '<p class="muted">农场还没种东西 —— 去种一株，下一局的击碎就会变成养分。</p>';
  }else{
    const lines2 = [];
    if(clearBonusShown > 1) lines2.push("今天的到期词清空了 → 养分 ×1.15");
    if(nutUnits > allKillsShown)
      lines2.push("救回了栽过的词 → 份数 " + allKillsShown + " → " + (Math.round(nutUnits * 10) / 10));
    const wx2 = curWeather();
    if(wx2.nut !== 1) lines2.push("今日" + wx2.n + " → 养分 ×" + wx2.nut.toFixed(2));
    const np = S.farm.plots.filter(p => p && CROPS[p.crop]).length;
    if(np > 1) lines2.push("养分按 " + np + " 块地分摊（总量随地块数开方增长）");
    if(nutGain.some(g => g.nb > 1)) lines2.push("有地块吃到了旁边珊瑚的加成");
    for(const s of lines2){
      const t = document.createElement("p");
      t.className = "muted"; t.style.margin = "0 0 6px";
      t.textContent = s;
      nb.appendChild(t);
    }
    for(const g of nutGain){
      const c = CROPS[g.crop], ripe = g.after >= g.need;
      const d = document.createElement("div"); d.className = "tier";
      d.innerHTML = "<b>" + esc(c.n) + '</b><div class="bar"><i style="width:' +
        (g.need ? g.after / g.need * 100 : 0).toFixed(1) + "%;background:" + c.c +
        '"></i></div><span>' + g.after + " / " + g.need + "</span>";
      nb.appendChild(d);
      if(ripe){
        const r = document.createElement("p");
        r.className = "muted"; r.style.cssText = "margin:2px 0 10px;color:#B8860B";
        r.textContent = "　" + c.n + " 已经成熟了，去农场收获。";
        nb.appendChild(r);
      }
    }
  }
}

function destroy(e){
  e.dead = true; kills++; combo++; bestCombo = Math.max(bestCombo, combo);
  const tk = e.item.kind === "s" ? "s" : e.item.t;
  killsByTier[tk] = (killsByTier[tk] || 0) + 1;
  const bad0 = progOf(e.item).bad | 0;
  /* 只往上加，不往下扣：新手的词都还没栽过，权重全是 1.0，收入和以前一样。
     把一个栽过两次的硬骨头救回来多给三成 —— 那是这一局里最值钱的一次复习。 */
  nutUnits += 1 + 0.3 * Math.min(1, bad0 / 2);
  sessFed.push({w: e.item.w, bad: bad0});
  coinBreak.kill += (TIER_COIN[tk] || 1) * (activeBoost === "echo" ? 1.5 : 1);
  if(e.hinted){
    // 用了浮标提示：给币、给养分，但明码标价 —— 这个词本局不计升级
    const p = progOf(e.item); p.ok++; p.due = Date.now() + DAY;
  }else{
    const g = grade(e.item, true);
    if(g.after > g.before){
      ups++;
      changed.push({w: e.item.w, zh: e.item.zh, before: g.before, after: g.after});
      if(g.after >= LEARNED_LV && g.before < LEARNED_LV){ newLearned++; coinBreak.learn += 5; }
      if(g.after >= MASTER_LV && g.before < MASTER_LV){ newMastered++; coinBreak.master += 15; }
    }
    // 学习阶段：低级词在本局内再来一次，第二次是升级后的形态
    // —— 否则同一天反复开局会永远只有 Lv0 新词
    if(g.after > g.before && g.after <= RELEARN_LV && !relearned.has(e.item)){
      relearned.add(e.item);
      const pos = Math.min(queue.length, 4 + ((Math.random() * 5) | 0));
      queue.splice(pos, 0, e.item);
      planned++;
    }
  }
  burst(e.x, e.y, SKIN[e.lv].f);
  ring(e.x, e.y, SKIN[e.lv].s, 4, 1);
  popText(e.x, e.y - 20, "+" + (10 + combo), "#0F6E56");
  wordTone(combo);
  // 连击里程碑：每 5 连一次冲击波 + 上行琶音
  if(combo >= 5 && combo % 5 === 0){
    milestone++;
    ring(e.x, e.y, "#FFD166", 7, 1.45);
    ring(e.x, e.y, "#FF8A5B", 4, .95);
    ring(e.x, e.y, "#FFF6E5", 3, .55);
    popText(e.x, e.y - 54, combo + " 连击！", "#E2622F", 26);
    burst(e.x, e.y, "#FFD166");
    coinBreak.combo += 5;
    flourish(Math.floor(combo / 5) - 1);
    const cp = document.getElementById("pCombo");
    cp.classList.remove("hot"); void cp.offsetWidth; cp.classList.add("hot");
  }
  if(S.voice !== "off") setTimeout(() => speakWord(e.item), 90);
  buf = ""; target = null; updateType();
  save();
}
function leak(e){
  e.dead = true; misses++; combo = 0; keyStreak = 0; lives--; damageFlash = .5;
  ring(e.x, e.y, "#E24B4A", 5);
  const g = grade(e.item, false);
  changed.push({w: e.item.w, zh: e.item.zh, before: g.before, after: g.after});
  queue.push(e.item); planned++;
  beep(150, .20, "triangle", .055);
  if(target === e.id){ buf = ""; target = null; updateType(); }
  save();
}
function getE(id){ return enemies.find(e => e.id === id && !e.dead); }

function onChar(ch){
  if(mode !== "play") return;
  if(target == null){
    const c = enemies.filter(e => !e.dead && e.answer.startsWith(ch));
    if(!c.length){ keyBad++; keyStreak = 0; shake(); return; }
    c.sort((a, b) => b.y - a.y);
    target = c[0].id; buf = ch; keyOk++; lockTone(); hitKey();
  }else{
    const e = getE(target);
    if(!e){ target = null; buf = ""; return onChar(ch); }
    if(e.answer[buf.length] === ch){ buf += ch; keyOk++; hitKey(); }
    else { keyBad++; keyStreak = 0; e.hitT = .22; shake(); return; }
  }
  const e = getE(target);
  if(!e){ target = null; buf = ""; return; }
  e.typed = buf; refreshDisp(e);
  sparkle(e.x + (Math.random() - .5) * 40, e.y + 46, SKIN[e.lv].f, 4);
  if(buf === e.answer) destroy(e);
  updateType();
}
function hitKey(){
  keyStreak++;
  if(keyStreak > bestStreak) bestStreak = keyStreak;
  keyTone();
  const el = document.getElementById("typed");
  el.classList.remove("pop"); void el.offsetWidth; el.classList.add("pop");
}
function shake(){
  const p = document.getElementById("pType");
  p.classList.remove("shake"); void p.offsetWidth; p.classList.add("shake");
  beep(190, .07, "sine", .035);
}
function updateType(){
  const e = target != null ? getE(target) : null;
  const el = document.getElementById("typed");
  if(!e){ el.textContent = ""; return; }
  const rest = e.answer.slice(buf.length).replace(/ /g, "·");
  el.innerHTML = esc(buf.replace(/ /g, "·")) + "<s>" + esc(rest) + "</s>";
}
function updateHud(){
  const done = Math.min(kills, planned);
  document.getElementById("tideBar").style.width =
    Math.max(0, Math.min(100, done / Math.max(1, planned) * 100)) + "%";
  document.getElementById("tideTxt").textContent = done + "/" + planned;
  document.getElementById("pCombo").textContent = "×" + combo + " 连击";
  let h = "";
  const hi = ART_SRC.icon_heart;
  for(let i = 0; i < Math.max(5, lives); i++){
    const on = i < lives;
    h += hi
      ? '<img class="heart" src="' + hi + '" alt="" style="opacity:' + (on ? 1 : .28) +
        ';filter:' + (on ? "none" : "grayscale(1)") + '">'
      : '<svg class="heart" viewBox="0 0 22 20"><path d="M11 19C1 11 4 3 11 7.5C18 3 21 11 11 19Z" fill="' +
        (on ? "#FF6B6B" : "#EADCB8") + '" stroke="' + (on ? "#8C2020" : "#C4AC7A") +
        '" stroke-width="2.5" stroke-linejoin="round"/></svg>';
  }
  document.getElementById("hearts").innerHTML = h;
}

function tick(now){
  requestAnimationFrame(tick);
  // 下限也要夹住：时间戳一旦回退（切标签页、系统时钟跳变）会算出负 dt，敌人会倒着飞
  const dt = Math.max(0, Math.min(.05, (now - last) / 1000)); last = now;
  waveT += dt * 1.1;
  if(damageFlash > 0) damageFlash -= dt;
  drawBg(dt);
  if(mode === "play"){
    spawnCd -= dt;
    const alive = enemies.filter(e => !e.dead).length;
    // 同屏上限随段位放宽：原来写死 3，打字快的人到后期会觉得"词都在排队、屏上没人"。
    // 只管"同时出现几个"，不碰总词数和排期，所以对记忆逻辑没有影响。
    const cap = 3 + (stageIdx() >= 3 ? 1 : 0) + (stageIdx() >= 6 ? 1 : 0);
    if(spawnCd <= 0 && queue.length && alive < cap){
      spawn(queue.shift()); spawnCd = .9 + Math.random() * .8;
    }
    for(const e of enemies){
      if(e.dead) continue;
      e.age += dt; if(e.hitT > 0) e.hitT -= dt;
      e.y += e.vy * dt;
      if(e.y >= seaY - 24) leak(e);
    }
    enemies = enemies.filter(e => !e.dead);
    for(const e of enemies) drawCreature(e);
    updateHud();
    if(lives <= 0 || (!queue.length && !enemies.some(e => !e.dead))) endGame();
  }
  drawRings(dt); drawBits(dt); drawFloats(dt);
}
requestAnimationFrame(t => { last = t; tick(t); });

/* ========== 输入 ========== */
/* ══ 手机键盘 ══
   塔防原本只读 window.keydown。手机上没有物理键盘，
   而系统软键盘只在有输入框聚焦时才弹出 —— 所以必须挂一个隐形输入框。
   桌面端不能启用：那样 keydown 和 input 会各收一遍，等于每个字母打两次。 */
// 裸写 navigator 在没有它的环境里会直接抛 ReferenceError，必须 typeof 兜住
const IS_TOUCH = (function(){
  try{
    if(typeof window === "undefined") return false;
    if("ontouchstart" in window) return true;
    return typeof navigator !== "undefined" && (navigator.maxTouchPoints | 0) > 0;
  }catch(e){ return false; }
})();
function setupTouch(){
  if(!IS_TOUCH) return;
  if(document.body && document.body.classList) document.body.classList.add("touch");
  const k = document.getElementById("mobKey");
  if(!k) return;
  k.addEventListener("input", () => {
    const v = k.value;
    k.value = "";
    if(mode !== "play") return;
    for(const ch of v){
      if(ch === " ") onChar(" ");
      else if(/[a-zA-Z0-9']/.test(ch)) onChar(ch.toLowerCase());
    }
  });
  // 软键盘的退格通常不产生可见字符，得单独接
  k.addEventListener("keydown", ev => {
    if(mode !== "play") return;
    if(ev.key === "Backspace" && buf.length){
      ev.preventDefault();
      buf = buf.slice(0, -1);
      const e = getE(target);
      if(e){ e.typed = buf; refreshDisp(e); }
      if(!buf.length) target = null;
      updateType();
    }
  });
  // 键盘弹出会把可视区压掉一半，危险线得跟着走，否则怪物在键盘底下就撞线了
  if(window.visualViewport){
    window.visualViewport.addEventListener("resize", () => { try{ resize(); }catch(e){} });
  }
}
function focusMobKey(){
  if(!IS_TOUCH) return;
  const k = document.getElementById("mobKey");
  if(k){ try{ k.value = ""; k.focus(); }catch(e){} }
}
function blurMobKey(){
  const k = document.getElementById("mobKey");
  if(k){ try{ k.blur(); }catch(e){} }
}

window.addEventListener("keydown", ev => {
  if(mode !== "play") return;
  if(IS_TOUCH && ev.target && ev.target.id === "mobKey") return;   // 手机走 input 那条路
  resumeAudio();                   // 系统随时可能挂起音频，按键时兜底唤醒
  if(ev.key === "Escape"){ ev.preventDefault(); endGame(); return; }
  if(ev.key === "ArrowDown"){ ev.preventDefault(); bumpSpeed(1); return; }
  if(ev.key === "ArrowUp"){ ev.preventDefault(); bumpSpeed(-1); return; }
  if(ev.key === "Tab"){
    ev.preventDefault();
    const t = target != null ? getE(target) : enemies.filter(e => !e.dead).sort((a, b) => b.y - a.y)[0];
    if(t) speak(t.item.w);
    return;
  }
  if(ev.key === "Backspace"){
    ev.preventDefault();
    if(buf.length){
      buf = buf.slice(0, -1);
      const e = getE(target);
      if(e){ e.typed = buf; refreshDisp(e); }
      if(!buf.length) target = null;
      updateType();
    }
    return;
  }
  if(ev.metaKey || ev.ctrlKey || ev.altKey) return;
  if(ev.key === " "){ ev.preventDefault(); onChar(" "); return; }
  if(ev.key.length === 1 && /[a-zA-Z0-9']/.test(ev.key)){ ev.preventDefault(); onChar(ev.key.toLowerCase()); }
});
cv.addEventListener("pointerdown", ev => {
  if(mode !== "play") return;
  let best = null, bd = 1e9;
  for(const e of enemies){
    if(e.dead) continue;
    const d = Math.hypot(e.x - ev.clientX, e.y + 30 - ev.clientY);
    if(d < bd){ bd = d; best = e; }
  }
  if(best && bd < 110) speak(best.item.w);
});

/* ========== 界面 ========== */
function showScreen(id){
  for(const s of document.querySelectorAll(".screen")) s.classList.remove("on");
  const tb = document.getElementById("topbar");
  if(id){
    document.getElementById(id).classList.add("on");
    tb.classList.add("on");
    document.getElementById("tbCoin").textContent = (S.farm.coin || 0).toLocaleString();
    document.getElementById("tbPearl").textContent = S.farm.pearl || 0;
    applyIcons();
  }else{
    tb.classList.remove("on");
  }
}
// 有图标立绘就换掉 CSS 画的那两个小圆点
// 列表项左侧缩略图；没这张立绘就返回空串，布局自动收拢
function thumb(key){
  const src = ART_SRC[key];
  return src ? "<i class='thumb' style=\"background-image:url(" + src + ")\"></i>" : "";
}
function applyIcons(){
  const map = [["tbCoinIcon", "icon_coin"], ["tbPearlIcon", "icon_pearl"]];
  for(const [id, key] of map){
    const el = document.getElementById(id);
    if(el && ART_SRC[key]){
      el.style.backgroundImage = "url(" + ART_SRC[key] + ")";
      el.style.backgroundSize = "contain";
      el.style.backgroundRepeat = "no-repeat";
      el.style.backgroundPosition = "center";
    }
  }
  // 结算页宝箱：有图才显示，没图这一格不占位
  const chest = document.getElementById("rChest");
  if(chest && ART_SRC.icon_chest){
    chest.style.backgroundImage = "url(" + ART_SRC.icon_chest + ")";
    chest.classList.add("on");
  }
  // 标题艺术字：有立绘就换图，没有则保留 CSS 渐变字
  const brand = document.getElementById("brand");
  if(brand && ART_SRC.logo_title){
    brand.classList.add("img");
    const bw = brand.querySelector(".bw");
    if(bw) bw.style.backgroundImage = "url(" + ART_SRC.logo_title + ")";
  }
  // 农场专属背景
  const sf = document.getElementById("scFarm");
  if(sf && ART_SRC.bg_farm){
    sf.style.backgroundImage = "url(" + ART_SRC.bg_farm + ")";
    sf.classList.add("hasbg");
  }
}
function refreshHome(){
  const items = deckItems();
  const total = items.length;
  const lr = learnedCount(items), ms = masteredCount(items);
  const seen = countAtLeast(0, items) - lr;
  document.getElementById("total").textContent = total;
  document.getElementById("learned").textContent = lr;
  document.getElementById("remain").textContent = total - lr;
  document.getElementById("sSeen").textContent = Math.max(0, seen);
  document.getElementById("sMaster").textContent = ms;
  document.getElementById("mainBar").style.width = (weightedProgress(items) * 100).toFixed(2) + "%";
  const s = buildSession();
  document.getElementById("sDue").textContent = s.due;
  document.getElementById("sNew").textContent = s.fresh;
  document.getElementById("sPlan").textContent = s.queue.length;
  // 顶部入口的数字和详情卡走同一份数据，不重算
  document.getElementById("eWordDue").textContent = s.due;
  document.getElementById("eWordSize").textContent = s.queue.length;
  document.getElementById("sStreak").textContent = S.streak || 0;
  document.getElementById("sCoin").textContent = (S.farm.coin || 0).toLocaleString();
  document.getElementById("tideNote").textContent = s.throttled
    ? "潮位偏高，本局" + (s.taking ? "只放 " + s.taking + " 个新词" : "暂停放新词")
      + "，先把旧账还上 —— 不扣任何东西，慢慢来。"
    : s.early
      ? "没有到期的词，本局提前拉了 " + s.early + " 个旧词回来复习，其余是新词。"
      : (s.due ? "有 " + s.due + " 个词到期了，打一局大概三到五分钟。"
               : "今天没有到期的词，正好学点新的。");
  const box = document.getElementById("tiers"); box.innerHTML = "";
  if(S.deck === "g"){
    for(let t = 1; t <= 5; t++){
      const g = items.filter(i => i.t === t && !i.custom);
      row(box, "T" + t + " " + DB.tn[t - 1], learnedCount(g), g.length);
    }
    const cu = items.filter(i => i.custom);
    if(cu.length) row(box, "我的生词", learnedCount(cu), cu.length);
  }else{
    const ws = items.filter(i => i.kind === "w"), ss = items.filter(i => i.kind === "s");
    row(box, "工地单词", learnedCount(ws), ws.length);
    row(box, "工地句子", learnedCount(ss), ss.length);
  }
  pills("deckSw", [["通用 2500", "g"], ["工地 500", "s"]], S.deck,
    v => { S.deck = v; stageDirty(); save(); refreshHome(); });
  pills("setSpeed", SPEEDS, S.speed || 2.5, v => { setSpeed(v, false); refreshHome(); });
  pills("setSentSize", [["每局最多 8 句 · 错句下局复习", 8]],
        8, v => { S.sentSize = v; save(); refreshHome(); });
  pills("setSentHint", [["默认关闭", 0], ["默认显示", 1]],
        S.sentHint | 0, v => { S.sentHint = v; save(); refreshHome(); });
  pills("setVoice", VOICES, S.voice || "after", v => { S.voice = v; save(); refreshHome(); });
  pills("setRate", RATES, S.rate || 0.85, v => { S.rate = v; save(); refreshHome(); });
  pills("setZh", ZHV, S.zhVoice === undefined ? 1 : S.zhVoice,
    v => { S.zhVoice = v; save(); refreshHome(); });
  pills("setBgm", BGMS, S.bgm === undefined ? 0.6 : S.bgm, v => {
    S.bgm = v; save();
    if(!v) stopBgm(); else if(bgmTimer){ stopBgm(); startBgm(); }
    refreshHome();
  });
  pills("setSfx", SFXS, S.sfx === undefined ? 1 : S.sfx, v => { S.sfx = v; save(); refreshHome(); });
  document.getElementById("voiceNote").textContent =
    S.voice === "spawn" ? "单词一出现就朗读。注意：Lv1、Lv2 关本来只给中文，开了这项等于直接把答案念给你。"
    : S.voice === "off" ? "完全静音。Lv3、Lv4 是听音关，关掉朗读后它们只能靠遮罩里的字母数硬猜。"
    : "答对的瞬间朗读一遍" + (S.zhVoice ? "：先英文，再中文释义。" : "。") +
      "每个词都听得到发音，又不会提前泄题 —— 推荐用这个。";
  try{ SENT.refreshCard(); }catch(e){}
}
/* ========== 农场界面 ========== */
/* ========== 农场作物：每种三个真形态 + 各自的地块环境 ========== */
// 每种作物的水色、沙色、装饰色，让六块地一眼能分辨
const CROP_SKIN = {
  kelp:    {w1:"#A8EDDF", w2:"#49BFB1", s1:"#F4E9CC", s2:"#D8C68F", dec:"#2E8B62", glow:"#7BE6C4"},
  coral:   {w1:"#FFD9C2", w2:"#5FBBE2", s1:"#FCE6C9", s2:"#E2C08E", dec:"#C4562A", glow:"#FFB48C"},
  anemone: {w1:"#FFD4E7", w2:"#7CB6E8", s1:"#FBE7D9", s2:"#E4C9A8", dec:"#B33C71", glow:"#FF9EC6"},
  jelly:   {w1:"#DED4FF", w2:"#6C8DE0", s1:"#E8DECB", s2:"#C7B48C", dec:"#4B3A8F", glow:"#C0AEFF"},
  conch:   {w1:"#DDF3FC", w2:"#4FA6D4", s1:"#F7F0DE", s2:"#DCCEA8", dec:"#3E7E99", glow:"#BFE6F7"},
  vine:    {w1:"#D8E4EA", w2:"#7695A6", s1:"#E9E1D0", s2:"#C4B89C", dec:"#4A5560", glow:"#A8BCC6"},
  starweed:{w1:"#BEEBFF", w2:"#3E96C8", s1:"#F1EBD6", s2:"#D3C49B", dec:"#2A6E9E", glow:"#9FE4FF"},
  vent:    {w1:"#FFD9B8", w2:"#E0713F", s1:"#F6E3CC", s2:"#DDBE95", dec:"#8C3A18", glow:"#FFB07A"},
  relic:   {w1:"#F7ECC8", w2:"#C9A24A", s1:"#F5EEDC", s2:"#D9C79E", dec:"#8A6A1B", glow:"#FFE9A8"},
  lotus:   {w1:"#E6F7FF", w2:"#78B9DD", s1:"#F7F0DA", s2:"#D7C28E", dec:"#4B92B8", glow:"#DDF7FF"},
  crystal: {w1:"#BFD8FF", w2:"#324F9C", s1:"#ECE4D2", s2:"#C6B58D", dec:"#F0A62E", glow:"#8DDCFF"},
  crown:   {w1:"#BDEEDD", w2:"#287D69", s1:"#F5E9C8", s2:"#D0BC83", dec:"#A77820", glow:"#FFE6A0"}
};
// 四段成长：萌芽 / 幼株 / 成长 / 成熟。只有真正满养分时才使用最终形态。
const CROP_STAGE_NAMES=["萌芽","幼株","成长","成熟"];
function cropStage(pct){ return pct >= 1 ? 3 : pct >= .62 ? 2 : pct >= .25 ? 1 : 0; }
function tp(d, dark, light, w1, w2){
  return '<g fill="none" stroke="' + dark + '" stroke-width="' + w1 + '" stroke-linecap="round" stroke-linejoin="round">' + d + "</g>" +
         '<g fill="none" stroke="' + light + '" stroke-width="' + w2 + '" stroke-linecap="round" stroke-linejoin="round">' + d + "</g>";
}
function cropArt(key, pct, w){
  const st0 = cropStage(pct);
  const W = w || 118, H = Math.round(W / 118 * 104);
  const url = ART_SRC["crop_" + key + "_" + st0];
  if(url){
    return '<img src="' + url + '" alt="" ' +
           'style="height:' + Math.round(W) + 'px;width:auto;object-fit:contain;' +
           'object-position:bottom">';
  }
  return cropArtVec(key, pct).replace('width="118" height="104"',
                                      'width="' + W + '" height="' + H + '"');
}
function cropArtVec(key, pct){
  const c = CROPS[key], st = cropStage(pct), F = c.c, D = c.d;
  // 少量旧扩展作物复用已有形状；稀有作物和首批六种都使用独立四阶段图片。
  key = c.shape || key;
  let g = "";

  if(key === "kelp"){
    if(st === 0){
      g = tp('<path d="M-6,0 q-3,-9 -1,-17"/><path d="M6,0 q3,-10 1,-19"/>', D, F, 9, 5);
    }else if(st === 1){
      g = tp('<path d="M-11,0 q-5,-15 -2,-30"/><path d="M0,0 q4,-18 0,-36"/><path d="M11,0 q6,-14 3,-27"/>', D, F, 10, 5.5) +
          '<path d="M-9,-20 q-9,-3 -12,-9" fill="none" stroke="' + F + '" stroke-width="4" stroke-linecap="round"/>';
    }else{
      g = tp('<path d="M-17,0 q-8,-18 -4,-38"/><path d="M-7,0 q-4,-24 -2,-48"/><path d="M3,0 q4,-26 1,-52"/>' +
             '<path d="M12,0 q7,-20 4,-40"/><path d="M20,0 q8,-14 6,-28"/>', D, F, 11, 6);
      g += '<g fill="none" stroke="' + F + '" stroke-width="4" stroke-linecap="round">' +
           '<path d="M-14,-26 q-10,-4 -14,-11"/><path d="M2,-34 q11,-4 15,-11"/></g>';
      g += '<circle cx="-20" cy="-46" r="3.4" fill="' + c.c + '"/><circle cx="9" cy="-56" r="3" fill="' + c.c + '"/>';
    }
  }

  else if(key === "coral"){
    if(st === 0){
      g = tp('<path d="M0,0 L0,-14"/><path d="M0,-14 L-8,-22"/>', D, F, 11, 6) +
          '<circle cx="-9" cy="-24" r="4" fill="' + F + '" stroke="' + D + '" stroke-width="2.5"/>';
    }else if(st === 1){
      g = tp('<path d="M0,0 L0,-16"/><path d="M0,-16 L-13,-32"/><path d="M0,-16 L11,-30"/>', D, F, 12, 6.5) +
          '<circle cx="-14" cy="-34" r="4.5" fill="' + F + '" stroke="' + D + '" stroke-width="2.5"/>' +
          '<circle cx="12" cy="-32" r="4" fill="' + F + '" stroke="' + D + '" stroke-width="2.5"/>';
    }else{
      g = tp('<path d="M0,0 L0,-15"/><path d="M0,-15 L-16,-31"/><path d="M0,-15 L14,-29"/>' +
             '<path d="M-16,-31 L-24,-45"/><path d="M-16,-31 L-8,-46"/>' +
             '<path d="M14,-29 L22,-44"/><path d="M14,-29 L7,-45"/>', D, F, 13, 7);
      for(const [x, y, r] of [[-25,-48,5],[-7,-49,4.4],[23,-47,5],[6,-48,4.2]]){
        g += '<circle cx="' + x + '" cy="' + y + '" r="' + r + '" fill="' + F + '" stroke="' + D + '" stroke-width="2.5"/>';
      }
      g += '<circle cx="-25" cy="-49.5" r="1.8" fill="#FFFFFF" opacity=".7"/>';
    }
  }

  else if(key === "anemone"){
    if(st === 0){
      g = '<ellipse cx="0" cy="-9" rx="11" ry="9" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          '<path d="M-4,-17 q4,-5 8,0" fill="none" stroke="' + D + '" stroke-width="3" stroke-linecap="round"/>';
    }else if(st === 1){
      g = tp('<path d="M0,-14 q-11,-8 -15,-18"/><path d="M0,-14 q-5,-12 -5,-22"/>' +
             '<path d="M0,-14 q5,-12 5,-22"/><path d="M0,-14 q11,-8 15,-18"/>', D, F, 6, 3) +
          '<ellipse cx="0" cy="-11" rx="15" ry="12" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          '<ellipse cx="-3" cy="-14" rx="6" ry="4" fill="#FFFFFF" opacity=".4"/>';
    }else{
      g = tp('<path d="M0,-16 q-17,-10 -23,-24"/><path d="M0,-16 q-12,-16 -13,-30"/>' +
             '<path d="M0,-16 q-4,-18 -3,-33"/><path d="M0,-16 q4,-18 3,-33"/>' +
             '<path d="M0,-16 q12,-16 13,-30"/><path d="M0,-16 q17,-10 23,-24"/>', D, F, 7, 3.4);
      g += '<ellipse cx="0" cy="-13" rx="20" ry="15" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>';
      g += '<ellipse cx="-4" cy="-17" rx="8" ry="5" fill="#FFFFFF" opacity=".45"/>';
      for(const [x, y] of [[-24,-42],[-14,-48],[4,-51],[14,-47],[24,-41]]){
        g += '<circle cx="' + x + '" cy="' + y + '" r="3.2" fill="' + F + '" opacity=".9"/>';
      }
    }
  }

  else if(key === "jelly"){
    const stem = '<path d="M0,0 L0,-18" fill="none" stroke="#2E8B62" stroke-width="6" stroke-linecap="round"/>';
    if(st === 0){
      g = stem + '<circle cx="0" cy="-24" r="8" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>';
    }else if(st === 1){
      g = '<path d="M0,0 L0,-24" fill="none" stroke="#2E8B62" stroke-width="6" stroke-linecap="round"/>' +
          '<path d="M0,-12 q-12,-3 -14,-11" fill="none" stroke="#2E8B62" stroke-width="5" stroke-linecap="round"/>' +
          tp('<path d="M-5,-27 q-2,6 0,10"/><path d="M5,-27 q3,6 1,9"/>', D, F, 5, 2.6) +
          '<path d="M-13,-29 A13,13 0 0 1 13,-29 Z" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          '<circle cx="-4" cy="-34" r="2.2" fill="#FFFFFF" opacity=".8"/>';
    }else{
      g = '<path d="M0,0 L0,-30" fill="none" stroke="#2E8B62" stroke-width="7" stroke-linecap="round"/>' +
          '<path d="M0,-13 q-15,-4 -18,-13" fill="none" stroke="#2E8B62" stroke-width="5.5" stroke-linecap="round"/>' +
          '<path d="M0,-21 q15,-4 18,-13" fill="none" stroke="#2E8B62" stroke-width="5.5" stroke-linecap="round"/>' +
          '<path d="M-18,-26 q-9,-2 -11,-8" fill="#3FBE92" stroke="#2E8B62" stroke-width="2.5"/>' +
          tp('<path d="M-9,-34 q-4,8 -1,14"/><path d="M0,-34 q3,10 0,15"/><path d="M9,-34 q5,8 2,13"/>', D, F, 5.5, 3);
      g += '<path d="M-19,-36 A19,18 0 0 1 19,-36 Z" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>';
      g += '<circle cx="-7" cy="-43" r="3" fill="#FFFFFF" opacity=".85"/>' +
           '<circle cx="3" cy="-46" r="2.2" fill="#FFFFFF" opacity=".7"/>' +
           '<circle cx="10" cy="-41" r="1.8" fill="#FFFFFF" opacity=".6"/>';
    }
  }

  else if(key === "conch"){
    if(st === 0){
      g = '<path d="M-13,-2 A13,13 0 0 1 13,-2 L7,4 L0,1 L-7,4 Z" fill="' + F +
          '" stroke="' + D + '" stroke-width="3" stroke-linejoin="round"/>' +
          '<path d="M0,3 L0,-12" fill="none" stroke="' + D + '" stroke-width="2" opacity=".6"/>';
    }else if(st === 1){
      let rib = "";
      for(let i = -2; i <= 2; i++) rib += '<path d="M0,4 L' + (i * 8) + "," + (-15 + Math.abs(i) * 2) + '"/>';
      g = '<path d="M-19,-4 A19,19 0 0 1 19,-4 L10,6 L0,2 L-10,6 Z" fill="' + F +
          '" stroke="' + D + '" stroke-width="3" stroke-linejoin="round"/>' +
          '<g fill="none" stroke="' + D + '" stroke-width="2" opacity=".65">' + rib + "</g>" +
          '<circle cx="0" cy="-9" r="5" fill="#FFFFFF" stroke="' + D + '" stroke-width="2.2"/>';
    }else{
      let rib = "";
      for(let i = -3; i <= 3; i++) rib += '<path d="M0,6 L' + (i * 9) + "," + (-24 + Math.abs(i) * 3) + '"/>';
      g = '<path d="M-28,-6 A28,28 0 0 1 28,-6 L15,8 L0,3 L-15,8 Z" fill="' + F +
          '" stroke="' + D + '" stroke-width="3" stroke-linejoin="round"/>' +
          '<g fill="none" stroke="' + D + '" stroke-width="2" opacity=".6">' + rib + "</g>" +
          '<circle cx="0" cy="-15" r="8.5" fill="#FFFFFF" stroke="' + D + '" stroke-width="2.6"/>' +
          '<circle cx="-3" cy="-18" r="2.8" fill="#FFFFFF"/>' +
          '<circle cx="-20" cy="-30" r="2.4" fill="#FFFFFF" opacity=".65"/>' +
          '<circle cx="18" cy="-33" r="2" fill="#FFFFFF" opacity=".55"/>';
    }
  }

  else{ // vine 钢铁藤
    const bolt = (x, y, r) => '<circle cx="' + x + '" cy="' + y + '" r="' + r + '" fill="#FFD166" stroke="' + D +
                              '" stroke-width="2.4"/><circle cx="' + (x - 1.4) + '" cy="' + (y - 1.6) + '" r="1.3" fill="#FFFFFF"/>';
    if(st === 0){
      g = '<rect x="-6" y="-20" width="12" height="20" rx="5" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          bolt(0, -20, 5) +
          '<path d="M-2,-6 q-9,-3 -10,-10" fill="none" stroke="#2E8B62" stroke-width="4.5" stroke-linecap="round"/>';
    }else if(st === 1){
      let rib = "";
      for(let y = -6; y > -32; y -= 8) rib += '<path d="M-6,' + y + " L6," + (y - 4) + '"/>';
      g = '<rect x="-7" y="-34" width="14" height="34" rx="6" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          '<g fill="none" stroke="' + D + '" stroke-width="2" opacity=".6">' + rib + "</g>" +
          '<path d="M-2,-5 q-14,-6 -11,-16 q4,-8 12,-3" fill="none" stroke="#2E8B62" stroke-width="5" stroke-linecap="round"/>' +
          '<path d="M-12,-20 q-9,-4 -10,-11 q8,-1 11,5 Z" fill="#3FBE92" stroke="#2E8B62" stroke-width="2.4" stroke-linejoin="round"/>' +
          bolt(0, -34, 5.5);
    }else{
      let rib = "";
      for(let y = -8; y > -50; y -= 8) rib += '<path d="M-7,' + y + " L7," + (y - 4) + '"/>';
      g = '<rect x="-8" y="-52" width="16" height="52" rx="7" fill="' + F + '" stroke="' + D + '" stroke-width="3"/>' +
          '<g fill="none" stroke="' + D + '" stroke-width="2.2" opacity=".6">' + rib + "</g>" +
          '<path d="M-3,-4 q-17,-7 -13,-18 q5,-10 15,-4 q14,7 11,-7 q-3,-12 -13,-9" fill="none" ' +
          'stroke="#2E8B62" stroke-width="5.5" stroke-linecap="round"/>' +
          '<path d="M-15,-23 q-11,-5 -12,-13 q9,-1 13,6 Z" fill="#3FBE92" stroke="#2E8B62" stroke-width="2.5" stroke-linejoin="round"/>' +
          '<path d="M10,-40 q12,-5 13,-13 q-10,-1 -14,6 Z" fill="#3FBE92" stroke="#2E8B62" stroke-width="2.5" stroke-linejoin="round"/>' +
          bolt(0, -52, 6.5) + bolt(0, -26, 4.5);
    }
  }

  // 复用矢量形状的扩展作物也要看得出第4阶段：成熟时长出一圈果实/星辉。
  if(st === 3){
    g += '<g fill="' + c.c + '" stroke="' + c.d + '" stroke-width="1.8">' +
         '<circle cx="-31" cy="-43" r="4"/><circle cx="31" cy="-39" r="3.5"/>' +
         '<path d="M0,-65 l3,6 7,1 -5,5 1,7 -6,-3 -6,3 1,-7 -5,-5 7,-1 Z"/></g>';
  }
  // 地里的小装饰：两侧的迷你海草，越成熟越多
  const k = CROP_SKIN[key] || CROP_SKIN.kelp;
  let side = '<g fill="none" stroke="' + k.dec + '" stroke-width="3.5" stroke-linecap="round" opacity=".55">' +
             '<path d="M-40,2 q-4,-9 -2,-16"/><path d="M38,2 q4,-8 2,-14"/>';
  if(st >= 1) side += '<path d="M-46,2 q-3,-7 -1,-11"/><path d="M45,2 q3,-6 1,-10"/>';
  if(st === 2) side += '<path d="M-33,2 q-2,-6 0,-10"/><path d="M32,2 q2,-5 0,-9"/>';
  side += "</g>";

  return '<svg width="118" height="104" viewBox="-59 -86 118 104" aria-hidden="true">' +
         '<ellipse cx="0" cy="2" rx="30" ry="6" fill="rgba(90,70,30,.16)"/>' +
         side + g + "</svg>";
}

/* ══════ 整图农场 ══════ */
// 12 块地在手机竖屏上每块只有 100px 宽，点都点不准，所以窄屏退回卡片列表
function mapMode(){
  try{ return window.innerWidth >= 780; }catch(e){ return true; }
}
/* 种什么来什么鱼 —— 这是 GDD 里"生态"那一条。
   鱼的立绘全是现成的，等于零成本地让农场和对局共用同一个海。 */
// 每种作物配一套自己的循环动作（CSS 类名后缀），别都用同一个摇摆
const ANIM = {kelp:"kelp", coral:"coral", anemone:"anem",
              jelly:"jelly", conch:"conch", vine:"vine",
              starweed:"kelp", vent:"anem", relic:"conch",
              lotus:"jelly", crystal:"coral", crown:"vine"};
// 鱼在水里的高度（%）。手动铺开，见 renderMap 里的说明
const FISH_TOP = [13, 34, 21, 45, 28, 16, 39, 24, 47, 31];
const ATTRACT = {
  kelp:    {k:"fish_s_gold",       n:"小黄鱼"},
  coral:   {k:"fish_clown",        n:"小丑鱼"},
  anemone: {k:"fish_puffer_peach", n:"河豚"},
  jelly:   {k:"fish_glow_pink",    n:"发光鱼"},
  conch:   {k:"fish_idol",         n:"蝴蝶鱼"},
  vine:    {k:"fish_silver",       n:"银枪鱼"},
  starweed:{k:"fish_s_teal",       n:"青纹鱼"},
  vent:    {k:"fish_gold2",        n:"金鳞鱼"},
  relic:   {k:"fish_veil",         n:"银纱鱼"},
  // 稀有作物吸引的是已有稀有鱼，不额外膨胀首批鱼类馆格数。
  lotus:   {k:"fish_idol",         n:"蝴蝶鱼"},
  crystal: {k:"fish_glow_pink",    n:"发光鱼"},
  crown:   {k:"fish_veil",         n:"银纱鱼"}
};
/* 居民按累计收获次数逐个入驻。用收获次数而不是词数，是因为
   收获次数本身就只能靠复习攒出来 —— 绕不过调度器，又比词数更贴"经营"的感觉。 */
const FOLK_UNLOCK = [
  {k:"crab",     at:1,  n:"小螃蟹"},
  {k:"hermit",   at:5,  n:"寄居蟹"},
  {k:"starfish", at:15, n:"海星"},
  {k:"shrimp",   at:30, n:"小虾"},
  {k:"seahorse", at:50, n:"海马"},
  {k:"octopus",  at:80, n:"章鱼宝宝"}
];
function folkHere(){
  const h = S.farm.harvested | 0;
  return FOLK_UNLOCK.filter(x => h >= x.at && ART_SRC["folk_" + x.k + "_f0"]);
}
/* 每种下一株就来一条鱼 —— 不是每种作物来一条。
   GDD 里那句"种得越多，鱼越多，世界越来越热闹"要成立，
   鱼的密度就得跟着地块数走：一种作物只来一条的话，
   种满 12 块地和种 6 块地的画面是一样的，多出来的六块白种了。
   空农场故意一条鱼都没有 —— 那个对比才是"世界被你养起来了"的来源。 */
function fishHere(){
  const out = [];
  for(const p of S.farm.plots){
    if(!p || !ATTRACT[p.crop]) continue;
    const a = ATTRACT[p.crop];
    if(!ART_SRC[a.k]) continue;
    out.push(a);
    if(out.length >= 10) break;      // 再多就糊成一片，也费性能
  }
  return out;
}
/* 一组交叉淡入的帧。纯 CSS：每帧 opacity 走一个梯形，相邻帧错开 1/n 个周期，
   交界处自然重叠成淡入淡出。不用 JS 定时器换 src —— GPU 合成，稳且省电。 */
function framesHtml(prefix, n, dur){
  let h = "";
  for(let i = 0; i < n; i++){
    const url = ART_SRC[prefix + "_f" + i];
    if(!url) continue;
    h += '<img src="' + url + '" alt="" style="animation-delay:' +
         (-(dur * i / n)).toFixed(2) + 's">';
  }
  return h;
}
function renderMap(){
  const box = document.getElementById("farmMap"), f = S.farm, wx = curWeather();
  box.innerHTML = "";
  if(ART_SRC.bg_farm) box.style.backgroundImage = "url(" + ART_SRC.bg_farm + ")";
  // 天气改整片海的色调，背景跟着变，每天开农场都不一样
  box.classList.toggle("night", wx.k === "moon");
  box.classList.toggle("storm", wx.k === "storm");
  box.classList.toggle("aurora", wx.k === "aurora");
  box.classList.toggle("flow", wx.k === "flow");
  box.classList.toggle("abyss", wx.k === "abyss");
  box.classList.toggle("bloom", wx.k === "bloom");
  box.classList.toggle("mist", wx.k === "mist");

  let html = "";
  for(let i = 0; i < 9; i++){
    const r = 4 + (i % 3) * 3;
    html += '<span class="mbub" style="left:' + (6 + i * 10.5).toFixed(1) +
            "%;bottom:2%;width:" + r + "px;height:" + r + "px;--bd:" +
            (7 + i % 4 * 2.5).toFixed(1) + "s;animation-delay:-" + (i * 1.7).toFixed(1) + 's"></span>';
  }
  /* 鱼只在水里游。高度写成一张表，别用取模算 ——
     第一版写的是 11 + (i*37)%38，周期太短，除了第一条全落在 45–48% 那一条带上，
     正好压在后排作物头顶，合成图上一眼就看出来是一排鱼在列队。
     这张表是手动铺开的：跨 12%–47%，相邻两条至少差 9%，且不重复成对。 */
  fishHere().forEach((a, i) => {
    const w = 44 + (i % 4) * 11;
    const top = FISH_TOP[i % FISH_TOP.length];
    // 有动作帧的鱼在农场里也摆尾（和居民一样用纯 CSS 交叉淡入）；
    // 没帧的就滑过去 —— 总比一条都不动强
    const nf = ART_SRC[a.k + "_f0"] ? ((FISH_FRAMES[a.k] || 2)) : 0;
    const fd = 1.5 + (i % 3) * .3;
    const inner = nf ? framesHtml(a.k, nf, fd)
                     : '<img src="' + ART_SRC[a.k] + '" alt="" ' +
                       'style="width:100%;animation:none">';
    html += '<span class="mlane" style="top:' + top + "%;--sd:" + (24 + (i % 5) * 6) +
            "s;animation-delay:-" + (i * 4.5).toFixed(1) + 's">' +
            '<span class="mfish" style="width:' + w + "px;height:" +
            Math.round(w * .62) + "px;--fd:" + fd.toFixed(2) + 's">' +
            inner + "</span></span>";
  });
  folkHere().forEach((x, i) => {
    const info = FOLK[x.k] || {n:1, fit:1};
    const w = Math.round(52 * (info.fit || 1));
    const dur = 2.2 + i * .35;
    html += '<span class="folk" style="left:' + (5 + i * 17).toFixed(1) +
            "%;width:" + w + "px;height:" + Math.round(w * 1.05) + "px;--fd:" +
            dur.toFixed(2) + 's" title="' + esc(x.n) + '">' +
            framesHtml("folk_" + x.k, info.n, dur) + "</span>";
  });
  for(let i = 0; i < MAX_SLOTS; i++){
    const P = PLOTS[i];
    if(i > f.slots) continue;                 // 只露出下一块待解锁的地
    const pos = "left:" + P.x + "%;top:" + P.y + "%;";
    if(i >= f.slots){
      html += '<div class="fplot" data-plot="' + i + '" style="' + pos + '">' +
              '<span class="spot lock">锁</span></div>';
      continue;
    }
    const p = f.plots[i];
    if(!p || !CROPS[p.crop]){
      html += '<div class="fplot" data-plot="' + i + '" style="' + pos + '">' +
              '<span class="spot">+</span></div>';
      continue;
    }
    const c = CROPS[p.crop], pct = c.need ? p.nut / c.need : 0;
    const ripe = p.nut >= c.need, hungry = (p.dry | 0) >= 2;
    const cw = Math.round(126 * P.s);
    html += '<div class="fplot a-' + ANIM[p.crop] + (ripe ? " ripe" : "") +
            (hungry ? " hungry" : "") +
            '" data-plot="' + i + '" style="' + pos + '" title="' + esc(c.n) + '">' +
            '<span class="art" style="transform:' + cropVariant(i) + '">' +
            cropArt(p.crop, pct, cw) + "</span>" +
            '<span class="pit"></span>' +
            '<svg class="deco" width="' + cw + '" height="' + Math.round(cw * .3) +
            '" viewBox="' + (-cw / 2) + " " + (-cw * .24) + " " + cw + " " + Math.round(cw * .3) +
            '" aria-hidden="true">' + decoSvg(i, cw) + "</svg>" +
            '<span class="ring"><i style="width:' + Math.min(100, pct * 100).toFixed(0) +
            "%;background:linear-gradient(90deg," + c.c + "," + c.d + ')"></i></span></div>';
  }
  box.innerHTML = html;
  box.querySelectorAll(".fplot").forEach(el => {
    el.onclick = () => openPlot(+el.getAttribute("data-plot"));
  });
}
/* 点开地块：把原来卡片上的信息和按钮收进一个浮条。
   地图上只留作物本身，界面才不会又变回一堆卡片。 */
function openPlot(i){
  const box = document.getElementById("farmMap"), f = S.farm;
  const old = box.querySelector(".fpop");
  if(old) old.remove();
  const d = document.createElement("div");
  d.className = "fpop";
  const p = f.plots[i];
  if(i >= f.slots){
    const full = SLOT_PRICE[i] || 3000, use = slotPearls(full);
    const price = full - use * PEARL_COIN;
    d.innerHTML = "<h4>第 " + (i + 1) + " 块地（未开垦）</h4><small>" + full + " 币" +
      (use ? "，可用 " + use + " 颗珍珠抵 " + use * PEARL_COIN + "，实付 " + price : "") +
      "</small>";
    const b = document.createElement("button");
    b.className = "sm pri"; b.textContent = "扩建";
    b.onclick = () => {
      if(f.coin < price){ toast("还差 " + (price - f.coin) + " 币"); return; }
      f.coin -= price; f.pearl -= use; f.slots++; f.plots.push(null);
      save(); refreshFarm(); toast("多了一块地");
    };
    d.appendChild(b);
  }else if(!p || !CROPS[p.crop]){
    d.innerHTML = "<h4>第 " + (i + 1) + " 块地 · 空地</h4>" +
                  "<small>在下面的种子铺挑一样种下去</small>";
  }else{
    const c = CROPS[p.crop], ripe = p.nut >= c.need, nb = growBonus(i);
    const mood = ripe ? "熟了" : ((p.dry | 0) >= 2 ? "饿了" : "长着呢");
    d.innerHTML = "<h4>" + esc(c.n) + "　<span style='font-weight:400;color:#5E7C8A'>" +
      "第 " + (i + 1) + " 块 · " + mood + "</span></h4><small>" + p.nut + " / " + c.need + " 养分" +
      (nb > 1 ? "　旁边的珊瑚 +" + Math.round((nb - 1) * 100) + "%" : "") +
      ((p.fed | 0) ? "　已吃掉 " + (p.fed | 0) + " 个词" : "") +
      "<br>" + esc(c.gn) + "</small>";
    const b = document.createElement("button");
    if(ripe){
      const pay = Math.round(c.yield * curWeather().coin);
      b.className = "sm pri"; b.textContent = "收获 " + pay + " 币";
      b.onclick = () => { harvest(i, pay); };
    }else{
      b.className = "sm"; b.textContent = "铲除";
      b.onclick = () => {
        if(confirm("铲掉这株" + c.n + "？已经攒的养分会清零，种子不退。")){
          f.plots[i] = null; save(); refreshFarm();
        }
      };
    }
    d.appendChild(b);
  }
  const x = document.createElement("button");
  x.className = "sm"; x.textContent = "关闭";
  x.onclick = () => d.remove();
  d.appendChild(x);
  box.appendChild(d);
}

function refreshFarm(){
  const f = S.farm;
  const useMap = mapMode();
  document.getElementById("farmMap").style.display = useMap ? "" : "none";
  document.getElementById("plots").style.display = useMap ? "none" : "";
  if(useMap) renderMap();
  document.getElementById("fCoin").textContent = f.coin.toLocaleString() + " 潮汐币";
  document.getElementById("fPearl").textContent = f.pearl + " 珍珠";
  const wx = curWeather();
  document.getElementById("wxDot").style.background = wx.c;
  document.getElementById("wxName").textContent = "今日海况：" + wx.n;
  document.getElementById("wxDesc").textContent = wx.d
    + "　养分 ×" + wx.nut.toFixed(2) + " · 收成 ×" + wx.coin.toFixed(2);
  const box = document.getElementById("plots"); box.innerHTML = "";
  for(let i = 0; i < MAX_SLOTS; i++){
    const d = document.createElement("div");
    if(i >= f.slots){
      if(i > f.slots) continue;
      const full = SLOT_PRICE[i] || 3000;
      const use = slotPearls(full);
      const price = full - use * PEARL_COIN;
      d.className = "plot lock";
      d.innerHTML = '<div class="scene">' +
        '<svg width="112" height="92" viewBox="0 0 112 92" aria-hidden="true" class="noSway">' +
        '<rect x="44" y="44" width="26" height="21" rx="5" fill="none" stroke="#8A897F" stroke-width="3.5"/>' +
        '<path d="M49,44 v-7 a8,8 0 0 1 16,0 v7" fill="none" stroke="#8A897F" stroke-width="3.5"/></svg></div>' +
        '<div class="info"><b>扩建地块</b><small>' + full + " 币" +
        (use ? "，用 " + use + " 颗珍珠抵掉 " + use * PEARL_COIN + "，实付 " + price : "") +
        "</small></div>";
      const b = document.createElement("button");
      b.className = "sm"; b.style.marginTop = "8px";
      b.textContent = f.coin >= price ? "扩建" : "币不够";
      b.disabled = false;
      b.onclick = () => {
        if(f.coin < price){ toast("还差 " + (price - f.coin) + " 币"); return; }
        f.coin -= price; f.pearl -= use;
        f.slots++; f.plots.push(null); save(); refreshFarm();
        toast(use ? "多了一块地（花掉 " + use + " 颗珍珠）" : "多了一块地");
      };
      (d.querySelector('.info') || d).appendChild(b);
      box.appendChild(d);
      continue;
    }
    const p = f.plots[i];
    if(!p){
      d.className = "plot empty";
      d.innerHTML = '<div class="scene"><span class="bb b1"></span>' +
        '<svg width="112" height="92" viewBox="0 0 112 92" aria-hidden="true" class="noSway">' +
        '<ellipse cx="56" cy="74" rx="26" ry="7" fill="#D8C08A"/>' +
        '<circle cx="56" cy="50" r="18" fill="none" stroke="#7FB6CC" stroke-width="3.5" stroke-dasharray="6 5"/>' +
        '<path d="M56,41 v18 M47,50 h18" stroke="#7FB6CC" stroke-width="3.5" stroke-linecap="round"/></svg></div>' +
        '<div class="info"><b>空地</b><small>去下面种子铺播种</small></div>';
      box.appendChild(d);
      continue;
    }
    const c = CROPS[p.crop], pct = c.need ? p.nut / c.need : 0, ripe = p.nut >= c.need;
    const sk = CROP_SKIN[p.crop], stg = cropStage(pct);
    d.className = "plot" + (ripe ? " ripe" : "");
    d.style.setProperty("--w1", sk.w1); d.style.setProperty("--w2", sk.w2);
    d.style.setProperty("--s1", sk.s1); d.style.setProperty("--s2", sk.s2);
    d.style.setProperty("--gl", sk.glow);
    const pbg = ART_SRC["plotbg_" + p.crop];
    if(pbg){ d.style.backgroundImage = "url(" + pbg + ")"; d.classList.add("hasbg"); }
    // 情绪：熟了 / 饿了（连着两局没喂到养分）/ 长着呢。
    // "饿了"不是惩罚，是提示这块地的档位和你最近在背的词对不上
    const mood = ripe ? ["熟了", "#1E7A55"]
               : ((p.dry | 0) >= 2 ? ["饿了", "#9A6B22"] : ["长着呢", "#4A6B7A"]);
    if((p.dry | 0) >= 2) d.classList.add("hungry");
    const nb2 = growBonus(i);
    d.innerHTML = '<div class="ptop"><b><i class="pno">' + (i + 1) + "</i>" + esc(c.n) +
      '</b><em class="lvb" style="background:' +
      c.c + ";color:" + c.d + '">' + CROP_STAGE_NAMES[stg] + "</em></div>" +
      '<div class="scene"><span class="bb b1"></span><span class="bb b2"></span><span class="bb b3"></span>' +
      cropArt(p.crop, pct) + (ripe ? '<span class="glow"></span>' : "") + "</div>" +
      '<div class="info">' +
      '<div class="nb"><i style="width:' + Math.min(100, pct * 100).toFixed(1) +
      "%;background:linear-gradient(180deg," + c.c + "," + c.d + ')"></i></div><small>' +
      p.nut + " / " + c.need + "　养分 · <b style='color:" + mood[1] + "'>" + mood[0] + "</b>" +
      (nb2 > 1 ? "　旁边的珊瑚 +" + Math.round((nb2 - 1) * 100) + "%" : "") +
      ((p.fed | 0) ? "<br>已吃掉 " + (p.fed | 0) + " 个词" : "") + "</small></div>";
    const b = document.createElement("button");
    b.className = "sm"; b.style.marginTop = "8px";
    if(ripe){
      const wx = curWeather();
      const pay = Math.round(c.yield * wx.coin);
      b.className = "sm pri"; b.textContent = "收获 " + pay + " 币";
      b.onclick = () => { harvest(i, pay); };
    }else{
      b.textContent = "铲除";
      b.onclick = () => {
        if(confirm("铲掉这株" + c.n + "？已经攒的养分会清零，种子不退。")){
          f.plots[i] = null; save(); refreshFarm();
        }
      };
    }
    (d.querySelector('.info') || d).appendChild(b);
    box.appendChild(d);
  }
  const mix = plantMix();
  const note = document.getElementById("mixNote");
  if(!mix) note.textContent = "地里空着 —— 下一局的新词按默认顺序从 T1 往后推。";
  else if(S.deck === "s") note.textContent = "当前是工地词库，农场配比只对通用 2500 词生效；工地场次照样给钢铁藤养分。";
  else{
    const names = {1:"T1", 2:"T2", 3:"T3", 4:"T4", 5:"T5", s:"工地"};
    let tot = 0; for(const t in mix) tot += mix[t];
    const parts = Object.keys(mix).map(t => names[t] + " " + Math.round(mix[t] / tot * 100) + "%");
    note.textContent = "下一局新词配比：" + parts.join(" · ") + "　（到期复习的词不受影响，永远优先）";
  }
  const ss = document.getElementById("shopSeeds"); ss.innerHTML = "";
  const tierName = {1:"T1 生活基础", 2:"T2 生活常用", 3:"T3 常用重点", 4:"T4 进阶重点", 5:"T5 难点突破", s:"工地词库"};
  for(const k of CROP_KEYS){
    const c = CROPS[k], own = f.seeds[k] | 0, gate=rareProgress(k), locked=!!c.rare&&!gate.ok;
    const d = document.createElement("div");
    d.className = "item seed-card rarity-" + (c.rare === "传说" ? "legend" : c.rare === "史诗" ? "epic" : c.rare ? "rare" : "normal") + (locked ? " seed-locked" : "");
    d.innerHTML = '<span class="seed-rarity">'+(c.rare||"普通")+'</span>' + thumb("seed_" + k) +
      "<b>" + esc(c.n) + "　<span class='seed-own'>×" + own + "</span></b>" +
      "<small>" + tierName[c.tier] + " · 四阶段成长<br>需养分 " + c.need + " · 产出 " + c.yield + " 币" +
      (c.pearl ? " + " + c.pearl + " 珍珠" : "") +
      "<br><b style='color:" + c.d + "'>" + esc(c.gn) + "</b>" +
      (c.rare ? "<br><span class='seed-req " + (locked?"no":"yes") + "'>" + (locked?"🔒 ":"✓ ") + esc(gate.text) + "</span>" : "") + "</small>";
    const row = document.createElement("div"); row.className = "row";
    const buy = document.createElement("button");
    buy.className = "sm";
    buy.textContent = locked ? "尚未解锁" : ("购买 " + c.seed + "币" + (c.pearlCost ? "＋" + c.pearlCost + "珠" : ""));
    buy.disabled = locked;
    buy.onclick = () => {
      const now=rareProgress(k);if(c.rare&&!now.ok){toast("解锁条件："+now.text);return;}
      if(f.coin < c.seed){ toast("还差 " + (c.seed - f.coin) + " 币"); return; }
      if((f.pearl|0) < (c.pearlCost|0)){toast("还差 "+((c.pearlCost|0)-(f.pearl|0))+" 颗珍珠");return;}
      f.coin -= c.seed;f.pearl-=(c.pearlCost|0);f.seeds[k]++;save();refreshFarm();beep(660,.1,"triangle",.08);
    };
    // 珍珠的第二个出口：贝生贝
    if(k === "conch"){
      const pb = document.createElement("button");
      pb.className = "sm"; pb.textContent = "用 " + CONCH_PEARL + " 珍珠换";
      pb.onclick = () => {
        if((f.pearl | 0) < CONCH_PEARL){
          toast("还差 " + (CONCH_PEARL - (f.pearl | 0)) + " 颗珍珠"); return;
        }
        f.pearl -= CONCH_PEARL; f.seeds[k]++; save(); refreshFarm();
        beep(880, .1, "triangle", .08);
      };
      row.appendChild(pb);
    }
    const plant = document.createElement("button");
    plant.className = "sm pri"; plant.textContent = "播种";
    plant.onclick = () => {
      if((f.seeds[k] | 0) <= 0){ toast("没有" + c.n + "的种子"); return; }
      const idx = f.plots.findIndex((x, i) => i < f.slots && !x);
      if(idx < 0){ toast("没有空地了，先收获或扩建"); return; }
      f.seeds[k]--; f.plots[idx] = {crop:k, nut:0}; save(); refreshFarm();
      toast(c.n + " 种下了");
    };
    row.appendChild(buy); row.appendChild(plant);
    if(c.rare&&locked){
      const route=document.createElement("button");route.className="sm";route.textContent="查看Boss";
      route.onclick=()=>{if(window.ECO&&ECO.openBosses)ECO.openBosses();else toast("从右侧图鉴进入Boss纪念馆");};
      row.appendChild(route);
    }
    d.appendChild(row); ss.appendChild(d);
  }
  const sb = document.getElementById("shopBoosts"); sb.innerHTML = "";
  for(const k of BOOST_KEYS){
    const b = BOOSTS[k], own = f.boosts[k] | 0, on = f.equipped === k;
    const d = document.createElement("div"); d.className = "item" + (on ? " on" : "");
    d.innerHTML = thumb("buff_" + k) +
      "<b>" + esc(b.n) + "　<span style='color:#96805A;font-weight:400'>×" + own + "</span></b>" +
      "<small>" + esc(b.d) + "</small>";
    const row = document.createElement("div"); row.className = "row";
    const buy = document.createElement("button");
    buy.className = "sm"; buy.textContent = "购买 " + b.p;
    buy.onclick = () => {
      if(f.coin < b.p){ toast("还差 " + (b.p - f.coin) + " 币"); return; }
      f.coin -= b.p; f.boosts[k]++; save(); refreshFarm(); beep(660, .1, "triangle", .08);
    };
    const eq = document.createElement("button");
    eq.className = "sm" + (on ? " pri" : ""); eq.textContent = on ? "已装备" : "装备";
    eq.onclick = () => {
      if(on){ f.equipped = null; }
      else if((f.boosts[k] | 0) <= 0){ toast("先买一个" + b.n); return; }
      else f.equipped = k;
      save(); refreshFarm();
    };
    row.appendChild(buy); row.appendChild(eq);
    d.appendChild(row); sb.appendChild(d);
  }
}
function pills(boxId, list, cur, pick){
  const box = document.getElementById(boxId);
  box.innerHTML = "";
  for(const [label, val] of list){
    const b = document.createElement("span");
    b.className = "pill" + (val === cur ? " on" : "");
    b.textContent = label; b.style.cursor = "pointer";
    b.onclick = () => pick(val);
    box.appendChild(b);
  }
}
function row(box, name, done, all){
  const d = document.createElement("div"); d.className = "tier";
  d.innerHTML = "<b>" + esc(name) + '</b><div class="bar"><i style="width:' +
    (all ? done / all * 100 : 0).toFixed(1) + '%"></i></div><span>' + done + " / " + all + "</span>";
  box.appendChild(d);
}

