/* ── 句潮接线 ──
   进句子局要把 mode 挪开："play" 是塔防的输入模式，
   停在那儿的话两套键盘处理会同时收键。 */
function enterSent(){
  resumeAudio();
  mode = "sent";
  document.getElementById("hud").classList.remove("on");
  stopBgm();
  SENT.start();
}
