document.getElementById("btnImport3").onclick = () => showScreen("scImport");
document.getElementById("btnSentHome").onclick = () => { mode = "home"; refreshHome(); showScreen("scHome"); };
document.getElementById("btnSentFarm").onclick = () => { mode = "home"; refreshFarm(); showScreen("scFarm"); };
document.getElementById("qQuit").onclick = () => { mode = "home"; SENT.end(); };
document.getElementById("btnSentGp").onclick = () => {
  const box = document.getElementById("qGpBox");
  if(!box) return;
  if(box.style.display !== "none"){ box.style.display = "none"; return; }
  box.style.display = "";
  const rows = Object.keys(S.sgp || {}).map(k => {
    const g = S.sgp[k];
    return {k, n:g.n, ok:g.ok, r: g.n ? g.ok / g.n : 1};
  }).filter(x => x.n >= 2).sort((a,b) => a.r - b.r);
  box.innerHTML = rows.length
    ? rows.slice(0, 14).map(x => {
        const pct = Math.round(x.r * 100);
        const col = pct < 60 ? "#E2603F" : pct < 80 ? "#D19A18" : "#2FA97C";
        return '<div class="sgp"><b>' + esc(x.k) + '</b><span class="mini"><i style="width:'
          + pct + '%;background:' + col + '"></i></span><span>' + x.ok + "/" + x.n + '</span></div>';
      }).join("")
    : '<p class="muted">还没有足够数据，多打几局句子就有了。</p>';
};
